   1→/**
   2→ * Omega Messages Endpoint
   3→ *
   4→ * POST: Send a message and stream the AI response via SSE
   5→ *
   6→ * This endpoint implements the core Omega chat functionality with:
   7→ * - Static tools: registrySearchTool and registryExecuteTool for external users
   8→ * - Dynamic tool loading: tools found via search are injected as callable tools
   9→ * - SSE streaming for real-time updates
  10→ */
  11→
  12→import { Prisma, prisma } from '@tpmjs/db';
  13→import { registryExecuteTool } from '@tpmjs/registry-execute';
  14→import { registrySearchTool } from '@tpmjs/registry-search';
  15→import {
  16→  jsonSchema,
  17→  type ModelMessage,
  18→  stepCountIs,
  19→  streamText,
  20→  tool,
  21→  wrapLanguageModel,
  22→} from 'ai';
  23→import { type NextRequest, NextResponse } from 'next/server';
  24→import { z } from 'zod';
  25→import { authenticateRequest } from '~/lib/api-keys/middleware';
  26→import { decryptApiKey } from '~/lib/crypto/api-keys';
  27→import { buildSystemPrompt } from '~/lib/omega/system-prompt';
  28→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
  29→
  30→// Devtools middleware - lazy loaded only in development
  31→let devtools: ReturnType<typeof import('@ai-sdk/devtools').devToolsMiddleware> | null = null;
  32→async function getDevtools() {
  33→  if (process.env.NODE_ENV !== 'development') return null;
  34→  if (!devtools) {
  35→    const { devToolsMiddleware } = await import('@ai-sdk/devtools');
  36→    devtools = devToolsMiddleware();
  37→    console.log('[Omega] AI SDK DevTools middleware initialized');
  38→  }
  39→  return devtools;
  40→}
  41→
  42→/**
  43→ * Warning about missing environment variables
  44→ */
  45→interface EnvVarWarning {
  46→  toolId: string;
  47→  toolName: string;
  48→  packageName: string;
  49→  envVar: {
  50→    name: string;
  51→    description: string;
  52→    required: boolean;
  53→  };
  54→}
  55→
  56→/**
  57→ * Fetch and decrypt user's environment variables
  58→ */
  59→async function getUserEnvVarsDecrypted(userId: string): Promise<Record<string, string>> {
  60→  try {
  61→    const keys = await prisma.userApiKey.findMany({ where: { userId } });
  62→    const result: Record<string, string> = {};
  63→    for (const key of keys) {
  64→      try {
  65→        result[key.keyName] = decryptApiKey(key.encryptedKey, key.keyIv);
  66→      } catch (error) {
  67→        console.error(`Failed to decrypt env var ${key.keyName}:`, error);
  68→        // Skip this key if decryption fails
  69→      }
  70→    }
  71→    return result;
  72→  } catch (error) {
  73→    console.error('Failed to fetch user env vars:', error);
  74→    return {};
  75→  }
  76→}
  77→
  78→/**
  79→ * Detect missing required environment variables for tools
  80→ */
  81→function detectMissingEnvVars(
  82→  tools: Array<{
  83→    toolId: string;
  84→    packageName: string;
  85→    name: string;
  86→    env?: Array<{ name: string; description?: string; required?: boolean }> | null;
  87→  }>,
  88→  userEnvVars: Record<string, string>
  89→): EnvVarWarning[] {
  90→  const warnings: EnvVarWarning[] = [];
  91→  const userEnvKeys = new Set(Object.keys(userEnvVars));
  92→
  93→  for (const t of tools) {
  94→    if (!t.env || !Array.isArray(t.env)) continue;
  95→
  96→    for (const envVar of t.env) {
  97→      // Only warn about required env vars that are not set
  98→      if (envVar.required && !userEnvKeys.has(envVar.name)) {
  99→        warnings.push({
 100→          toolId: t.toolId,
 101→          toolName: t.name,
 102→          packageName: t.packageName,
 103→          envVar: {
 104→            name: envVar.name,
 105→            description: envVar.description || '',
 106→            required: true,
 107→          },
 108→        });
 109→      }
 110→    }
 111→  }
 112→
 113→  // Deduplicate by env var name (same env var might be needed by multiple tools)
 114→  const seen = new Set<string>();
 115→  return warnings.filter((w) => {
 116→    if (seen.has(w.envVar.name)) return false;
 117→    seen.add(w.envVar.name);
 118→    return true;
 119→  });
 120→}
 121→
 122→/**
 123→ * Rate limit for Omega chat: 20 requests per minute
 124→ * Stricter limit because this involves multiple tool executions
 125→ */
 126→const OMEGA_RATE_LIMIT: RateLimitConfig = {
 127→  limit: 20,
 128→  windowSeconds: 60,
 129→};
 130→
 131→export const runtime = 'nodejs';
 132→export const dynamic = 'force-dynamic';
 133→export const maxDuration = 300; // 5 minutes for complex tool chains
 134→
 135→type RouteContext = {
 136→  params: Promise<{ id: string }>;
 137→};
 138→
 139→const SendMessageSchema = z.object({
 140→  message: z.string().min(1).max(10000),
 141→});
 142→
 143→// Executor service URL
 144→const EXECUTOR_URL =
 145→  process.env.TPMJS_EXECUTOR_URL ||
 146→  process.env.RAILWAY_EXECUTOR_URL ||
 147→  'https://executor.tpmjs.com';
 148→
 149→// In-memory conversation state for dynamically loaded tools
 150→// biome-ignore lint/suspicious/noExplicitAny: Tool types from AI SDK are complex
 151→const conversationStates = new Map<string, { loadedTools: Record<string, any> }>();
 152→
 153→/**
 154→ * Search for relevant tools based on user query
 155→ */
 156→async function searchRelevantTools(
 157→  query: string,
 158→  limit = 15,
 159→  requestUrl?: string
 160→): Promise<
 161→  Array<{
 162→    toolId: string;
 163→    packageName: string;
 164→    name: string;
 165→    description: string;
 166→    version: string;
 167→    importUrl: string;
 168→    inputSchema?: unknown;
 169→    env?: Array<{ name: string; description?: string; required?: boolean }>;
 170→  }>
 171→> {
 172→  const params = new URLSearchParams({
 173→    q: query,
 174→    limit: String(limit),
 175→  });
 176→
 177→  // Determine base URL from request or environment
 178→  let baseUrl: string;
 179→  if (process.env.VERCEL_URL) {
 180→    baseUrl = `https://${process.env.VERCEL_URL}`;
 181→  } else if (requestUrl) {
 182→    // Extract origin from the incoming request URL
 183→    const url = new URL(requestUrl);
 184→    baseUrl = url.origin;
 185→  } else {
 186→    // Fallback to PORT env var or default
 187→    const port = process.env.PORT || '3000';
 188→    baseUrl = `http://localhost:${port}`;
 189→  }
 190→
 191→  console.log(`🔍 Tool search using baseUrl: ${baseUrl}`);
 192→  const response = await fetch(`${baseUrl}/api/tools/search?${params}`);
 193→
 194→  if (!response.ok) {
 195→    console.error(`Tool search failed: ${response.status} ${response.statusText}`);
 196→    return [];
 197→  }
 198→
 199→  // biome-ignore lint/suspicious/noExplicitAny: API response types vary
 200→  const data = (await response.json()) as any;
 201→  const toolsArray = data.results?.tools || [];
 202→
 203→  // biome-ignore lint/suspicious/noExplicitAny: API response types vary
 204→  return toolsArray.map((t: any) => ({
 205→    toolId: `${t.package.npmPackageName}::${t.name}`,
 206→    packageName: t.package.npmPackageName,
 207→    name: t.name,
 208→    description: t.description || `Tool: ${t.name}`,
 209→    version: t.package.npmVersion,
 210→    importUrl: `https://esm.sh/${t.package.npmPackageName}@${t.package.npmVersion}`,
 211→    inputSchema: t.inputSchema,
 212→    env: t.package.env || [],
 213→  }));
 214→}
 215→
 216→/**
 217→ * Fetch the tool's inputSchema from the executor's loadAndDescribe endpoint.
 218→ * This is used when the schema isn't available in the database yet.
 219→ */
 220→async function fetchSchemaFromExecutor(toolMeta: {
 221→  packageName: string;
 222→  name: string;
 223→  version: string;
 224→  importUrl: string;
 225→}): Promise<unknown | null> {
 226→  try {
 227→    console.log(`📋 Fetching schema from executor for ${toolMeta.packageName}/${toolMeta.name}`);
 228→    const response = await fetch(`${EXECUTOR_URL}/load-and-describe`, {
 229→      method: 'POST',
 230→      headers: { 'Content-Type': 'application/json' },
 231→      body: JSON.stringify({
 232→        packageName: toolMeta.packageName,
 233→        name: toolMeta.name,
 234→        version: toolMeta.version,
 235→        importUrl: toolMeta.importUrl,
 236→      }),
 237→    });
 238→
 239→    if (!response.ok) {
 240→      console.warn(
 241→        `⚠️ Schema fetch failed (${response.status}) for ${toolMeta.packageName}/${toolMeta.name}`
 242→      );
 243→      return null;
 244→    }
 245→
 246→    // biome-ignore lint/suspicious/noExplicitAny: Executor response format varies
 247→    const result = (await response.json()) as any;
 248→    if (result.success && result.tool?.inputSchema) {
 249→      console.log(`✅ Got schema from executor for ${toolMeta.packageName}/${toolMeta.name}`);
 250→      return result.tool.inputSchema;
 251→    }
 252→    return null;
 253→  } catch (error) {
 254→    console.warn(`⚠️ Schema fetch error for ${toolMeta.packageName}/${toolMeta.name}:`, error);
 255→    return null;
 256→  }
 257→}
 258→
 259→/**
 260→ * Create a dynamic tool wrapper that executes via the sandbox executor
 261→ */
 262→async function createDynamicTool(
 263→  toolMeta: {
 264→    toolId: string;
 265→    packageName: string;
 266→    name: string;
 267→    description: string;
 268→    version: string;
 269→    importUrl: string;
 270→    inputSchema?: unknown;
 271→  },
 272→  userEnvVars: Record<string, string>
 273→) {
 274→  // If inputSchema is missing from the database, fetch it from the executor
 275→  let schema = toolMeta.inputSchema;
 276→  if (!schema) {
 277→    schema = await fetchSchemaFromExecutor(toolMeta);
 278→  }
 279→
 280→  return tool({
 281→    description: toolMeta.description,
 282→    inputSchema: schema
 283→      ? jsonSchema(schema as Parameters<typeof jsonSchema>[0])
 284→      : jsonSchema({
 285→          type: 'object',
 286→          properties: {},
 287→          additionalProperties: true,
 288→        }),
 289→    // biome-ignore lint/suspicious/noExplicitAny: Dynamic tool params
 290→    execute: async (params: any) => {
 291→      console.log(`🚀 Executing ${toolMeta.packageName}/${toolMeta.name} with params:`, params);
 292→
 293→      try {
 294→        const response = await fetch(`${EXECUTOR_URL}/execute-tool`, {
 295→          method: 'POST',
 296→          headers: { 'Content-Type': 'application/json' },
 297→          body: JSON.stringify({
 298→            packageName: toolMeta.packageName,
 299→            name: toolMeta.name,
 300→            version: toolMeta.version,
 301→            importUrl: toolMeta.importUrl,
 302→            params,
 303→            env: userEnvVars,
 304→          }),
 305→        });
 306→
 307→        // biome-ignore lint/suspicious/noExplicitAny: API response types vary
 308→        const result = (await response.json()) as any;
 309→
 310→        if (!result.success) {
 311→          console.error(`❌ Tool execution failed: ${result.error}`);
 312→          // Return error as result instead of throwing so AI can see it
 313→          return {
 314→            error: true,
 315→            message: result.error || 'Tool execution failed',
 316→            toolId: toolMeta.toolId,
 317→          };
 318→        }
 319→
 320→        console.log(`✅ Tool executed in ${result.executionTimeMs}ms`);
 321→        return result.output;
 322→      } catch (error) {
 323→        console.error(`❌ Tool execution error:`, error);
 324→        return {
 325→          error: true,
 326→          message: error instanceof Error ? error.message : 'Unknown error during tool execution',
 327→          toolId: toolMeta.toolId,
 328→        };
 329→      }
 330→    },
 331→  });
 332→}
