 334→/**
 335→ * Sanitize tool name to be a valid JS identifier.
 336→ * OpenAI has a 64-character limit for tool names.
 337→ */
 338→function sanitizeToolName(name: string): string {
 339→  const sanitized = name
 340→    .replace(/@/g, '')
 341→    .replace(/\//g, '_')
 342→    .replace(/-/g, '_')
 343→    .replace(/::/g, '_')
 344→    .replace(/[^a-zA-Z0-9_]/g, '');
 345→
 346→  // OpenAI API requires tool names <= 64 characters
 347→  if (sanitized.length <= 64) {
 348→    return sanitized;
 349→  }
 350→
 351→  // Truncate but try to keep the meaningful part (tool name at the end)
 352→  // Use last 64 chars if it starts with a letter, otherwise use first 64
 353→  const last64 = sanitized.slice(-64);
 354→  if (/^[a-zA-Z]/.test(last64)) {
 355→    return last64;
 356→  }
 357→  return sanitized.slice(0, 64);
 358→}
 359→
 360→/**
 361→ * Add dynamically found tools to the conversation state (parallel schema fetching)
 362→ */
 363→async function addToolsToConversation(
 364→  conversationId: string,
 365→  toolMetas: Array<{
 366→    toolId: string;
 367→    packageName: string;
 368→    name: string;
 369→    description: string;
 370→    version: string;
 371→    importUrl: string;
 372→    inputSchema?: unknown;
 373→  }>,
 374→  userEnvVars: Record<string, string>
 375→): Promise<string[]> {
 376→  if (!conversationStates.has(conversationId)) {
 377→    conversationStates.set(conversationId, { loadedTools: {} });
 378→  }
 379→  // biome-ignore lint/style/noNonNullAssertion: We just ensured it exists
 380→  const state = conversationStates.get(conversationId)!;
 381→
 382→  // Filter to only tools not yet loaded
 383→  const newToolMetas = toolMetas.filter((tm) => {
 384→    const sanitizedName = sanitizeToolName(tm.toolId);
 385→    return !state.loadedTools[sanitizedName];
 386→  });
 387→
 388→  if (newToolMetas.length === 0) return [];
 389→
 390→  // Fetch schemas in parallel using Promise.allSettled
 391→  const results = await Promise.allSettled(
 392→    newToolMetas.map(async (toolMeta) => {
 393→      const sanitizedName = sanitizeToolName(toolMeta.toolId);
 394→      const dynamicTool = await createDynamicTool(toolMeta, userEnvVars);
 395→      return { sanitizedName, dynamicTool };
 396→    })
 397→  );
 398→
 399→  const addedTools: string[] = [];
 400→  for (const result of results) {
 401→    if (result.status === 'fulfilled') {
 402→      const { sanitizedName, dynamicTool } = result.value;
 403→      state.loadedTools[sanitizedName] = dynamicTool;
 404→      addedTools.push(sanitizedName);
 405→      console.log(`✅ Added dynamic tool: ${sanitizedName}`);
 406→    } else {
 407→      console.error(`❌ Failed to create tool wrapper:`, result.reason);
 408→    }
 409→  }
 410→
 411→  return addedTools;
 412→}
