 414→/**
 415→ * POST /api/omega/conversations/[id]/messages
 416→ * Send a message and stream the AI response via SSE
 417→ */
 418→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 419→  // --- Tier A: Auth, params, body in parallel ---
 420→  const [authResult, { id: conversationId }, body] = await Promise.all([
 421→    authenticateRequest(),
 422→    context.params,
 423→    request.json(),
 424→  ]);
 425→
 426→  if (!authResult.authenticated || !authResult.userId) {
 427→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 428→  }
 429→
 430→  // Check rate limit
 431→  const rateLimitResponse = checkRateLimit(request, OMEGA_RATE_LIMIT);
 432→  if (rateLimitResponse) {
 433→    return rateLimitResponse;
 434→  }
 435→
 436→  const parsed = SendMessageSchema.safeParse(body);
 437→  if (!parsed.success) {
 438→    return NextResponse.json(
 439→      { success: false, error: 'Invalid request', details: parsed.error.flatten() },
 440→      { status: 400 }
 441→    );
 442→  }
 443→
 444→  const userId = authResult.userId;
 445→
 446→  try {
 447→    // --- Tier B: All user/conversation data in parallel ---
 448→    const [conversation, user, userSettings, userEnvVars] = await Promise.all([
 449→      prisma.omegaConversation.findUnique({
 450→        where: { id: conversationId },
 451→        include: { participants: { select: { userId: true } } },
 452→      }),
 453→      prisma.user.findUnique({
 454→        where: { id: userId },
 455→        select: { id: true, name: true, email: true },
 456→      }),
 457→      prisma.omegaUserSettings.findUnique({ where: { userId } }),
 458→      getUserEnvVarsDecrypted(userId),
 459→    ]);
 460→
 461→    if (!conversation) {
 462→      return NextResponse.json(
 463→        { success: false, error: 'Conversation not found' },
 464→        { status: 404 }
 465→      );
 466→    }
 467→
 468→    // Check if user is owner or participant
 469→    const isOwner = userId === conversation.ownerId;
 470→    const isParticipant = conversation.participants.some((p) => p.userId === userId);
 471→
 472→    if (!isOwner && !isParticipant) {
 473→      return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
 474→    }
 475→
 476→    console.log(`🔑 Loaded ${Object.keys(userEnvVars).length} user env vars`);
 477→
 478→    // Check OpenAI API key early before doing more work
 479→    const apiKey = process.env.OPENAI_API_KEY;
 480→    if (!apiKey) {
 481→      return NextResponse.json(
 482→        { success: false, error: 'Omega is not configured. Missing OPENAI_API_KEY.' },
 483→        { status: 500 }
 484→      );
 485→    }
 486→
 487→    // --- Tier C: Write operations + tool search + recent messages in parallel ---
 488→    const [, , relevantTools, recentMessages] = await Promise.all([
 489→      prisma.omegaConversation.update({
 490→        where: { id: conversationId },
 491→        data: { executionState: 'running' },
 492→      }),
 493→      prisma.omegaMessage.create({
 494→        data: {
 495→          conversationId,
 496→          role: 'USER',
 497→          content: parsed.data.message,
 498→          authorId: user?.id,
 499→          authorEmail: user?.email,
 500→          authorName: user?.name,
 501→        },
 502→      }),
 503→      searchRelevantTools(parsed.data.message, 10, request.url),
 504→      prisma.omegaMessage.findMany({
 505→        where: { conversationId },
 506→        orderBy: { createdAt: 'desc' },
 507→        take: 20,
 508→      }),
 509→    ]);
 510→
 511→    console.log(`📦 Found ${relevantTools.length} relevant tools via BM25`);
 512→    recentMessages.reverse();
 513→
 514→    // Initialize or get conversation state
 515→    if (!conversationStates.has(conversationId)) {
 516→      conversationStates.set(conversationId, { loadedTools: {} });
 517→    }
 518→    // biome-ignore lint/style/noNonNullAssertion: We just ensured it exists
 519→    const state = conversationStates.get(conversationId)!;
 520→
 521→    // Detect missing required environment variables (sync, no await needed)
 522→    const missingEnvVars = detectMissingEnvVars(relevantTools, userEnvVars);
 523→    if (missingEnvVars.length > 0) {
 524→      console.log(
 525→        `⚠️ Missing ${missingEnvVars.length} required env vars:`,
 526→        missingEnvVars.map((w) => w.envVar.name)
 527→      );
 528→    }
 529→
 530→    // Get the provider model (using OpenAI by default)
 531→    const { createOpenAI } = await import('@ai-sdk/openai');
 532→    const openai = createOpenAI({ apiKey });
 533→    const baseModel = openai('gpt-4.1-mini');
 534→
 535→    // Wrap with devtools middleware in development
 536→    const devtoolsMiddleware = await getDevtools();
 537→    const model = devtoolsMiddleware
 538→      ? wrapLanguageModel({ model: baseModel, middleware: devtoolsMiddleware })
 539→      : baseModel;
 540→
 541→    if (devtoolsMiddleware) {
 542→      console.log('[Omega] Model wrapped with DevTools middleware');
 543→    }
 544→
 545→    // Open SSE stream early — do tool loading inside start()
 546→    const stream = new ReadableStream({
 547→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
 548→      async start(controller) {
 549→        const encoder = new TextEncoder();
 550→
 551→        const sendEvent = (event: string, data: unknown) => {
 552→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
 553→          controller.enqueue(encoder.encode(message));
 554→        };
 555→
 556→        // Emit env var warnings at the start of the stream
 557→        if (missingEnvVars.length > 0) {
 558→          sendEvent('env.warning', { missingEnvVars });
 559→        }
 560→
 561→        try {
 562→          // --- Status: searching for tools ---
 563→          sendEvent('status', { phase: 'searching', message: 'Finding relevant tools...' });
 564→
 565→          // Add auto-discovered tools to conversation state (parallel schema fetching)
 566→          const autoAddedTools = await addToolsToConversation(
 567→            conversationId,
 568→            relevantTools,
 569→            userEnvVars
 570→          );
 571→          console.log(`✨ Auto-added ${autoAddedTools.length} new tools`);
 572→
 573→          // --- Status: tools loaded ---
 574→          const dynamicToolCount = Object.keys(state.loadedTools).length;
 575→          if (dynamicToolCount > 0) {
 576→            sendEvent('status', {
 577→              phase: 'loading',
 578→              message: `Loading ${dynamicToolCount} tool${dynamicToolCount !== 1 ? 's' : ''}...`,
 579→            });
 580→          }
 581→
 582→          // Build final tools object: static tools + dynamically loaded tools
 583→          // biome-ignore lint/suspicious/noExplicitAny: Dynamic tool types
 584→          const allTools: Record<string, any> = {
 585→            registrySearchTool,
 586→            registryExecuteTool,
 587→            ...state.loadedTools,
 588→          };
 589→
 590→          console.log(
 591→            `🔧 ${Object.keys(allTools).length} total tools available (2 static + ${dynamicToolCount} dynamic)`
 592→          );
 593→
 594→          // Build AI SDK messages
 595→          const messages: ModelMessage[] = [];
 596→
 597→          // Build tool list for system prompt
 598→          const staticToolsList = [
 599→            '- registrySearchTool: Search the TPMJS registry to find AI SDK tools by keyword. Returns toolIds for registryExecuteTool.',
 600→            '- registryExecuteTool: Execute any tool from the TPMJS registry by toolId. Use registrySearchTool first to find tools.',
 601→          ].join('\n');
 602→
 603→          const dynamicToolsList = Object.entries(state.loadedTools)
 604→            .map(([name, t]) => {
 605→              const tl = t as { description?: string };
 606→              return `- ${name}: ${tl.description || 'No description'}`;
 607→            })
 608→            .join('\n');
 609→
 610→          // Add system prompt with available tools
 611→          const baseSystemPrompt = buildSystemPrompt({
 612→            customSystemPrompt: userSettings?.customSystemPrompt,
 613→            pinnedToolIds: userSettings?.pinnedToolIds || [],
 614→          });
 615→
 616→          const systemPrompt = `${baseSystemPrompt}
 617→
 618→## Static Tools (Always Available)
 619→
 620→These tools let you access the entire TPMJS registry of 1M+ tools:
 621→
 622→${staticToolsList}
 623→
 624→## Dynamically Loaded Tools
 625→
 626→These tools have been discovered and loaded for this conversation. Call them directly:
 627→
 628→${dynamicToolsList || 'No tools loaded yet. Use registrySearchTool to find tools, or they will be auto-loaded based on your requests.'}
 629→
 630→## How to Use Tools
 631→
 632→1. **To find a tool**: Use registrySearchTool with a keyword (e.g., "weather", "web scraping", "database")
 633→2. **To execute a found tool**: Use registryExecuteTool with the toolId returned from search
 634→3. **Direct execution**: If a tool is already loaded above, call it directly by name
 635→
 636→## Example Workflow
 637→
 638→User: "Get the weather in Tokyo"
 639→1. Use registrySearchTool to find weather tools
 640→2. Use registryExecuteTool to execute the found tool
 641→   OR call a loaded tool directly if available
 642→
 643→Remember: Your value is in EXECUTING tools to get real results, not just describing what tools could do.`;
 644→
 645→          messages.push({ role: 'system', content: systemPrompt });
 646→
 647→          // Add conversation history
 648→          for (const msg of recentMessages.slice(0, -1)) {
 649→            // Exclude the message we just added
 650→            if (msg.role === 'USER') {
 651→              messages.push({ role: 'user', content: msg.content });
 652→            } else if (msg.role === 'ASSISTANT') {
 653→              if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
 654→                const toolCallParts = (
 655→                  msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
 656→                ).map((tc) => ({
 657→                  type: 'tool-call' as const,
 658→                  toolCallId: tc.toolCallId,
 659→                  toolName: tc.toolName,
 660→                  input: tc.args,
 661→                }));
 662→
 663→                const content: Array<
 664→                  | { type: 'text'; text: string }
 665→                  | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
 666→                > = [];
 667→
 668→                if (msg.content) {
 669→                  content.push({ type: 'text', text: msg.content });
 670→                }
 671→                content.push(...toolCallParts);
 672→                messages.push({ role: 'assistant', content });
 673→              } else {
 674→                messages.push({ role: 'assistant', content: msg.content });
 675→              }
 676→            } else if (msg.role === 'TOOL') {
 677→              // Handle tool results (stored in toolCalls as a workaround)
 678→              const toolResults = msg.toolCalls as Array<{
 679→                toolCallId: string;
 680→                toolName: string;
 681→                output: unknown;
 682→              }> | null;
 683→              if (toolResults && toolResults.length > 0) {
 684→                for (const tr of toolResults) {
 685→                  messages.push({
 686→                    role: 'tool',
 687→                    content: [
 688→                      {
 689→                        type: 'tool-result' as const,
 690→                        toolCallId: tr.toolCallId,
 691→                        toolName: tr.toolName,
 692→                        output: {
 693→                          type: 'json' as const,
 694→                          value: tr.output as Parameters<typeof JSON.stringify>[0],
 695→                        },
 696→                      },
 697→                    ],
 698→                  });
 699→                }
 700→              }
 701→            }
 702→          }
 703→
 704→          // Add new user message
 705→          messages.push({ role: 'user', content: parsed.data.message });
 706→
 707→          // --- Status: streaming ---
 708→          sendEvent('status', { phase: 'streaming', message: 'Generating response...' });
 709→
 710→          let fullContent = '';
 711→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
 712→            new Map();
 713→          const pendingToolResults: Array<{
 714→            toolCallId: string;
 715→            toolName: string;
 716→            output: unknown;
 717→          }> = [];
 718→          let inputTokens = 0;
 719→          let outputTokens = 0;
 720→
 721→          // Track per-tool start times for accurate executionTimeMs
 722→          const toolStartTimes = new Map<string, number>();
 723→
 724→          const result = streamText({
 725→            model,
 726→            messages,
 727→            tools: Object.keys(allTools).length > 0 ? allTools : undefined,
 728→            stopWhen: stepCountIs(10), // Allow up to 10 tool calls for search + execute patterns
 729→            onChunk: async (chunk) => {
 730→              // Handle tool call (complete tool call with args)
 731→              if (chunk.chunk.type === 'tool-call') {
 732→                const input =
 733→                  'input' in chunk.chunk
 734→                    ? chunk.chunk.input
 735→                    : 'args' in chunk.chunk
 736→                      ? (chunk.chunk as { args: unknown }).args
 737→                      : {};
 738→
 739→                // Track tool start time
 740→                toolStartTimes.set(chunk.chunk.toolCallId, Date.now());
 741→
 742→                // Fire-and-forget: create tool run record
 743→                prisma.omegaToolRun
 744→                  .create({
 745→                    data: {
 746→                      conversationId,
 747→                      toolName: chunk.chunk.toolName,
 748→                      input: input as Prisma.InputJsonValue,
 749→                      status: 'running',
 750→                    },
 751→                  })
 752→                  .catch(console.error);
 753→
 754→                sendEvent('run.step.tool.started', {
 755→                  toolCallId: chunk.chunk.toolCallId,
 756→                  toolName: chunk.chunk.toolName,
 757→                  input,
 758→                });
 759→              }
 760→            },
 761→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex tool result handling
 762→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
 763→              // Capture tool calls
 764→              if (toolCalls && Array.isArray(toolCalls)) {
 765→                for (const tc of toolCalls) {
 766→                  if (!toolCallsMap.has(tc.toolCallId)) {
 767→                    const args =
 768→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
 769→                    toolCallsMap.set(tc.toolCallId, {
 770→                      toolCallId: tc.toolCallId,
 771→                      toolName: tc.toolName,
 772→                      args,
 773→                    });
 774→                  }
 775→                }
 776→              }
 777→
 778→              // Process tool results
 779→              if (toolResults && toolResults.length > 0) {
 780→                for (const tr of toolResults) {
 781→                  const isError =
 782→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
 783→
 784→                  // Check if this is a registrySearchTool result - inject found tools
 785→                  if (
 786→                    tr.toolName === 'registrySearchTool' &&
 787→                    tr.output &&
 788→                    typeof tr.output === 'object'
 789→                  ) {
 790→                    const searchOutput = tr.output as {
 791→                      tools?: Array<{
 792→                        toolId: string;
 793→                        package: string;
 794→                        name: string;
 795→                        description: string;
 796→                      }>;
 797→                    };
 798→                    if (searchOutput.tools && Array.isArray(searchOutput.tools)) {
 799→                      console.log(
 800→                        `🔍 registrySearchTool found ${searchOutput.tools.length} tools - injecting dynamically`
 801→                      );
 802→
 803→                      // Convert search results to tool metadata format and add to conversation
 804→                      const toolMetas = searchOutput.tools.map((t) => {
 805→                        const parts = t.toolId.split('::');
 806→                        const pkg = t.package || parts[0] || t.toolId;
 807→                        const toolName = t.name || parts[1] || 'unknown';
 808→                        return {
 809→                          toolId: t.toolId,
 810→                          packageName: pkg,
 811→                          name: toolName,
 812→                          description: t.description || `Tool: ${toolName}`,
 813→                          version: 'latest',
 814→                          importUrl: `https://esm.sh/${pkg}`,
 815→                        };
 816→                      });
 817→
 818→                      const newlyAdded = await addToolsToConversation(
 819→                        conversationId,
 820→                        toolMetas,
 821→                        userEnvVars
 822→                      );
 823→                      if (newlyAdded.length > 0) {
 824→                        sendEvent('tools.loaded', {
 825→                          newTools: newlyAdded,
 826→                          totalDynamicTools: Object.keys(state.loadedTools).length,
 827→                        });
 828→                      }
 829→                    }
 830→                  }
 831→
 832→                  // Compute per-tool execution time
 833→                  const toolStart = toolStartTimes.get(tr.toolCallId);
 834→                  const executionTimeMs = toolStart ? Date.now() - toolStart : 0;
 835→                  toolStartTimes.delete(tr.toolCallId);
 836→
 837→                  // Build update data for tool run
 838→                  const toolRunUpdateData: Prisma.OmegaToolRunUpdateManyMutationInput = {
 839→                    output: tr.output as Prisma.InputJsonValue,
 840→                    status: isError ? 'error' : 'success',
 841→                    completedAt: new Date(),
 842→                    executionTimeMs,
 843→                  };
 844→
 845→                  // Add error message if the tool execution failed
 846→                  if (isError) {
 847→                    toolRunUpdateData.error =
 848→                      typeof tr.output === 'object' && tr.output && 'error' in tr.output
 849→                        ? String((tr.output as { error: unknown }).error)
 850→                        : 'Unknown error';
 851→                  }
 852→
 853→                  // Fire-and-forget: update tool run record
 854→                  prisma.omegaToolRun
 855→                    .updateMany({
 856→                      where: {
 857→                        conversationId,
 858→                        toolName: tr.toolName,
 859→                        status: 'running',
 860→                      },
 861→                      data: toolRunUpdateData,
 862→                    })
 863→                    .catch(console.error);
 864→
 865→                  sendEvent('run.step.tool.completed', {
 866→                    toolCallId: tr.toolCallId,
 867→                    toolName: tr.toolName,
 868→                    output: tr.output,
 869→                    isError,
 870→                  });
 871→
 872→                  pendingToolResults.push({
 873→                    toolCallId: tr.toolCallId,
 874→                    toolName: tr.toolName,
 875→                    output: tr.output,
 876→                  });
 877→                }
 878→              }
 879→
 880→              if (usage) {
 881→                inputTokens += usage.inputTokens ?? 0;
 882→                outputTokens += usage.outputTokens ?? 0;
 883→              }
 884→            },
 885→          });
 886→
 887→          // Stream text chunks
 888→          for await (const chunk of result.textStream) {
 889→            fullContent += chunk;
 890→            sendEvent('message.delta', { content: chunk });
 891→          }
 892→
 893→          // Get final usage
 894→          const finalUsage = await result.usage;
 895→          if (finalUsage) {
 896→            inputTokens = finalUsage.inputTokens ?? inputTokens;
 897→            outputTokens = finalUsage.outputTokens ?? outputTokens;
 898→          }
 899→
 900→          const allToolCalls = Array.from(toolCallsMap.values());
 901→
 902→          // Save assistant message
 903→          const assistantMessage = await prisma.omegaMessage.create({
 904→            data: {
 905→              conversationId,
 906→              role: 'ASSISTANT',
 907→              content: fullContent,
 908→              toolCalls:
 909→                allToolCalls.length > 0
 910→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
 911→                  : Prisma.JsonNull,
 912→              inputTokens,
 913→              outputTokens,
 914→            },
 915→          });
 916→
 917→          // Save tool results as TOOL messages
 918→          if (pendingToolResults.length > 0) {
 919→            await prisma.omegaMessage.create({
 920→              data: {
 921→                conversationId,
 922→                role: 'TOOL',
 923→                content: 'Tool results',
 924→                toolCalls: pendingToolResults as unknown as Prisma.InputJsonValue,
 925→              },
 926→            });
 927→          }
 928→
 929→          // Update conversation: tokens, state, and title if first message pair
 930→          // Uses recentMessages.length to avoid count() query
 931→          const isFirstMessagePair = recentMessages.length <= 1;
 932→          await prisma.omegaConversation.update({
 933→            where: { id: conversationId },
 934→            data: {
 935→              executionState: 'idle',
 936→              inputTokensTotal: { increment: inputTokens },
 937→              outputTokensTotal: { increment: outputTokens },
 938→              ...(isFirstMessagePair && !conversation.title
 939→                ? {
 940→                    title:
 941→                      parsed.data.message.slice(0, 50) +
 942→                      (parsed.data.message.length > 50 ? '...' : ''),
 943→                  }
 944→                : {}),
 945→            },
 946→          });
 947→
 948→          sendEvent('run.completed', {
 949→            messageId: assistantMessage.id,
 950→            inputTokens,
 951→            outputTokens,
 952→            toolCallCount: allToolCalls.length,
 953→            staticTools: ['registrySearchTool', 'registryExecuteTool'],
 954→            dynamicToolsLoaded: Object.keys(state.loadedTools),
 955→            autoDiscoveredTools: relevantTools.map((t) => ({
 956→              toolId: t.toolId,
 957→              name: t.name,
 958→              packageName: t.packageName,
 959→              description: t.description,
 960→            })),
 961→          });
 962→
 963→          controller.close();
 964→        } catch (error) {
 965→          console.error('Stream error:', error);
 966→
 967→          // Update conversation state on error
 968→          await prisma.omegaConversation.update({
 969→            where: { id: conversationId },
 970→            data: { executionState: 'idle' },
 971→          });
 972→
 973→          sendEvent('run.failed', {
 974→            error: error instanceof Error ? error.message : 'Unknown error',
 975→          });
 976→          controller.close();
 977→        }
 978→      },
 979→    });
 980→
 981→    return new Response(stream, {
 982→      headers: {
 983→        'Content-Type': 'text/event-stream',
 984→        'Cache-Control': 'no-cache',
 985→        Connection: 'keep-alive',
 986→      },
 987→    });
 988→  } catch (error) {
 989→    console.error('Message handler error:', error);
 990→
 991→    // Reset conversation state
 992→    await prisma.omegaConversation.update({
 993→      where: { id: conversationId },
 994→      data: { executionState: 'idle' },
 995→    });
 996→
 997→    return NextResponse.json(
 998→      { success: false, error: error instanceof Error ? error.message : 'Unknown error' },
 999→      { status: 500 }
1000→    );
1001→  }
1002→}
