  1→/**
  2→ * Scenario Execution Service
  3→ *
  4→ * Orchestrates scenario execution using collection tools with AI SDK.
  5→ * Executes scenarios by building tools from the associated collection
  6→ * and running them through an LLM agent loop.
  7→ */
  8→
  9→import { openai } from '@ai-sdk/openai';
 10→import type { Collection, Package, Scenario, ScenarioRun, Tool } from '@prisma/client';
 11→import { prisma } from '@tpmjs/db';
 12→import { generateText, stepCountIs } from 'ai';
 13→
 14→import { createToolDefinition } from '../ai-agent/tool-executor-agent';
 15→import { parseExecutorConfig, resolveExecutorConfig } from '../executors';
 16→import {
 17→  determineFinalVerdict,
 18→  type EvaluationResult,
 19→  type EvaluatorModelId,
 20→  evaluateScenarioRun,
 21→  runAssertions,
 22→} from './evaluate';
 23→
 24→const DEFAULT_EVALUATOR: EvaluatorModelId = 'gpt-4.1-mini';
 25→const DEFAULT_MODEL = 'gpt-4.1-mini';
 26→const MAX_RETRIES = 1;
 27→const MAX_TOOL_STEPS = 10;
 28→
 29→/**
 30→ * Error categories for scenario execution
 31→ */
 32→export type ScenarioErrorCategory =
 33→  | 'COLLECTION_NOT_FOUND'
 34→  | 'NO_COLLECTION'
 35→  | 'NO_TOOLS'
 36→  | 'TOOL_BUILD_ERROR'
 37→  | 'EXECUTION_ERROR'
 38→  | 'EVALUATION_ERROR'
 39→  | 'QUOTA_EXCEEDED'
 40→  | 'UNKNOWN_ERROR';
 41→
 42→/**
 43→ * Structured error for scenario execution
 44→ */
 45→export class ScenarioExecutionError extends Error {
 46→  constructor(
 47→    message: string,
 48→    public readonly category: ScenarioErrorCategory,
 49→    public readonly context?: Record<string, unknown>
 50→  ) {
 51→    super(message);
 52→    this.name = 'ScenarioExecutionError';
 53→  }
 54→}
