 56→/**
 57→ * Structured logging for scenario execution
 58→ */
 59→function logScenarioEvent(
 60→  event: 'start' | 'tools_built' | 'execution_complete' | 'evaluation_complete' | 'error' | 'retry',
 61→  scenarioId: string,
 62→  data?: Record<string, unknown>
 63→): void {
 64→  const logEntry = {
 65→    timestamp: new Date().toISOString(),
 66→    event: `scenario.${event}`,
 67→    scenarioId,
 68→    ...data,
 69→  };
 70→
 71→  // In production, this could be sent to a logging service
 72→  // For now, we use structured console logging that can be parsed
 73→  if (process.env.NODE_ENV === 'development') {
 74→    console.log('[Scenario]', JSON.stringify(logEntry, null, 2));
 75→  }
 76→}
