 96→/**
 97→ * Check and decrement user's daily quota
 98→ */
 99→export async function checkAndDecrementQuota(
100→  userId: string
101→): Promise<{ allowed: boolean; remaining: number }> {
102→  const now = new Date();
103→  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());
104→
105→  // Get or create quota record
106→  let quota = await prisma.scenarioQuota.findUnique({
107→    where: { userId },
108→  });
109→
110→  if (!quota) {
111→    quota = await prisma.scenarioQuota.create({
112→      data: {
113→        userId,
114→        dailyLimit: 50,
115→        dailyUsed: 0,
116→        lastResetAt: startOfDay,
117→      },
118→    });
119→  }
120→
121→  // Reset quota if it's a new day
122→  if (quota.lastResetAt < startOfDay) {
123→    quota = await prisma.scenarioQuota.update({
124→      where: { userId },
125→      data: {
126→        dailyUsed: 0,
127→        lastResetAt: startOfDay,
128→      },
129→    });
130→  }
131→
132→  // Check if quota allows another run
133→  if (quota.dailyUsed >= quota.dailyLimit) {
134→    return { allowed: false, remaining: 0 };
135→  }
136→
137→  // Decrement quota
138→  await prisma.scenarioQuota.update({
139→    where: { userId },
140→    data: {
141→      dailyUsed: { increment: 1 },
142→    },
143→  });
144→
145→  return { allowed: true, remaining: quota.dailyLimit - quota.dailyUsed - 1 };
146→}
