148→/**
149→ * Update scenario metrics based on run result
150→ */
151→export async function updateScenarioMetrics(
152→  scenarioId: string,
153→  status: 'pass' | 'fail' | 'error'
154→): Promise<void> {
155→  const scenario = await prisma.scenario.findUnique({
156→    where: { id: scenarioId },
157→  });
158→
159→  if (!scenario) return;
160→
161→  const { totalRuns } = scenario;
162→  let { consecutivePasses, consecutiveFails, qualityScore } = scenario;
163→
164→  if (status === 'pass') {
165→    consecutivePasses += 1;
166→    consecutiveFails = 0;
167→    // Bonus for streaks: +0.05 per pass + (streak bonus), max 1.0
168→    qualityScore = Math.min(1.0, qualityScore + 0.05 + consecutivePasses * 0.01);
169→  } else {
170→    consecutiveFails += 1;
171→    consecutivePasses = 0;
172→    // Penalty for fails: -0.1 per fail + (streak penalty), min 0
173→    qualityScore = Math.max(0, qualityScore - 0.1 - consecutiveFails * 0.02);
174→  }
175→
176→  await prisma.scenario.update({
177→    where: { id: scenarioId },
178→    data: {
179→      consecutivePasses,
180→      consecutiveFails,
181→      qualityScore,
182→      totalRuns: totalRuns + 1,
183→      lastRunAt: new Date(),
184→      lastRunStatus: status,
185→    },
186→  });
187→}
