189→/**
190→ * Execute a scenario using real agent with collection tools
191→ *
192→ * 1. Creates run record with 'pending' status
193→ * 2. Builds AI SDK tools from the scenario's collection
194→ * 3. Executes the scenario prompt with multi-step tool loop
195→ * 4. Evaluates the result with LLM judgment
196→ * 5. Runs any configured assertions
197→ * 6. Updates scenario quality metrics based on result
198→ *
199→ * @param scenario The scenario to execute
200→ * @param userId The user triggering the execution
201→ * @param options Execution options
202→ */
203→export async function executeScenario(
204→  scenario: Scenario,
205→  userId: string,
206→  options: ExecutionOptions = {}
207→): Promise<ExecutionResult> {
208→  const { evaluatorModel = DEFAULT_EVALUATOR } = options;
209→
210→  logScenarioEvent('start', scenario.id, {
211→    userId,
212→    collectionId: scenario.collectionId,
213→    evaluatorModel,
214→  });
215→
216→  // Create run record
217→  const run = await prisma.scenarioRun.create({
218→    data: {
219→      scenarioId: scenario.id,
220→      userId,
221→      status: 'pending',
222→    },
223→  });
224→
225→  let lastError: Error | null = null;
226→  let retryCount = 0;
227→
228→  // Retry loop
229→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
230→    retryCount = attempt;
231→
232→    if (attempt > 0) {
233→      logScenarioEvent('retry', scenario.id, {
234→        attempt,
235→        previousError: lastError?.message,
236→      });
237→    }
238→
239→    try {
240→      // Update status to running
241→      await prisma.scenarioRun.update({
242→        where: { id: run.id },
243→        data: {
244→          status: 'running',
245→          startedAt: new Date(),
246→          retryCount: attempt,
247→        },
248→      });
249→
250→      // Execute scenario using real agent with collection tools
251→      const executionResult = await executeWithAgent(scenario);
252→
253→      // Evaluate with LLM
254→      let evaluation: EvaluationResult;
255→      try {
256→        evaluation = await evaluateScenarioRun(
257→          scenario.prompt,
258→          executionResult.output,
259→          executionResult.conversation,
260→          evaluatorModel
261→        );
262→      } catch (evalError) {
263→        throw new ScenarioExecutionError(
264→          `Evaluation failed: ${evalError instanceof Error ? evalError.message : 'Unknown error'}`,
265→          'EVALUATION_ERROR',
266→          { scenarioId: scenario.id, evaluatorModel, error: String(evalError) }
267→        );
268→      }
269→
270→      // Run assertions if defined
271→      const assertions = scenario.assertions as {
272→        regex?: string[];
273→        schema?: Record<string, unknown>;
274→      } | null;
275→      const assertionResults = assertions
276→        ? runAssertions(executionResult.output, assertions)
277→        : null;
278→
279→      // Determine final verdict
280→      const finalStatus = determineFinalVerdict(evaluation, assertionResults);
281→
282→      logScenarioEvent('evaluation_complete', scenario.id, {
283→        verdict: finalStatus,
284→        evaluatorVerdict: evaluation.verdict,
285→        evaluatorConfidence: evaluation.confidence,
286→        assertionsPassed: assertionResults?.passed.length ?? 0,
287→        assertionsFailed: assertionResults?.failed.length ?? 0,
288→      });
289→
290→      // Update run record
291→      const updatedRun = await prisma.scenarioRun.update({
292→        where: { id: run.id },
293→        data: {
294→          status: finalStatus,
295→          conversation: executionResult.conversation as object,
296→          output: executionResult.output,
297→          evaluatorModel,
298→          evaluatorVerdict: evaluation.verdict,
299→          evaluatorReason: evaluation.reason,
300→          assertionResults: assertionResults as object,
301→          inputTokens: executionResult.usage.inputTokens,
302→          outputTokens: executionResult.usage.outputTokens,
303→          totalTokens: executionResult.usage.totalTokens,
304→          executionTimeMs: executionResult.durationMs,
305→          completedAt: new Date(),
306→        },
307→      });
308→
309→      // Update scenario metrics
310→      await updateScenarioMetrics(scenario.id, finalStatus);
311→
312→      return { run: updatedRun, success: finalStatus === 'pass' };
313→    } catch (error) {
314→      lastError = error as Error;
315→
316→      // If this is the last attempt, mark as error
317→      if (attempt === MAX_RETRIES) {
318→        // Extract error category if it's a ScenarioExecutionError
319→        const errorCategory =
320→          error instanceof ScenarioExecutionError ? error.category : 'UNKNOWN_ERROR';
321→        const errorContext = error instanceof ScenarioExecutionError ? error.context : undefined;
322→
323→        logScenarioEvent('error', scenario.id, {
324→          category: errorCategory,
325→          message: lastError.message,
326→          context: errorContext,
327→          retryCount,
328→        });
329→
330→        const errorRun = await prisma.scenarioRun.update({
331→          where: { id: run.id },
332→          data: {
333→            status: 'error',
334→            retryCount,
335→            errorLog: JSON.stringify({
336→              message: lastError.message,
337→              category: errorCategory,
338→              context: errorContext,
339→              stack: lastError.stack,
340→            }),
341→            completedAt: new Date(),
342→          },
343→        });
344→
345→        await updateScenarioMetrics(scenario.id, 'error');
346→
347→        return { run: errorRun, success: false };
348→      }
349→    }
350→  }
351→
352→  // Should never reach here, but TypeScript needs this
353→  throw lastError || new Error('Unknown execution error');
354→}
