356→/**
357→ * Fetch collection with all tool relations needed for execution
358→ */
359→async function fetchCollectionWithTools(collectionId: string): Promise<CollectionWithTools | null> {
360→  return prisma.collection.findUnique({
361→    where: { id: collectionId },
362→    include: {
363→      tools: {
364→        include: {
365→          tool: {
366→            include: { package: true },
367→          },
368→        },
369→        orderBy: { position: 'asc' },
370→      },
371→    },
372→  });
373→}
