375→/**
376→ * Sanitize npm package name to valid tool name
377→ * OpenAI limits tool names to 64 characters
378→ */
379→function sanitizeToolName(name: string): string {
380→  const sanitized = name.replace(/[@/]/g, '-').replace(/^-+/, '');
381→  return sanitized.slice(0, 64);
382→}
383→
384→/**
385→ * Parse environment variables from JSON field
386→ */
387→function parseEnvVars(envVars: unknown): Record<string, string> {
388→  if (!envVars || typeof envVars !== 'object') {
389→    return {};
390→  }
391→  const result: Record<string, string> = {};
392→  for (const [key, value] of Object.entries(envVars)) {
393→    if (typeof value === 'string') {
394→      result[key] = value;
395→    }
396→  }
397→  return result;
398→}
399→
400→/**
401→ * Build AI SDK tools from a collection
402→ * Similar to buildAgentTools but works directly with Collection
403→ */
404→function buildCollectionTools(
405→  collection: CollectionWithTools
406→): Record<string, ReturnType<typeof createToolDefinition>> {
407→  const tools: Record<string, ReturnType<typeof createToolDefinition>> = {};
408→  const seenTools = new Set<string>();
409→
410→  // Parse collection-level executor config
411→  const collectionExecutorConfig = parseExecutorConfig(
412→    collection.executorType,
413→    collection.executorConfig
414→  );
415→
416→  // Resolve executor config (collection config or system default)
417→  const resolvedConfig = resolveExecutorConfig(null, collectionExecutorConfig);
418→
419→  // Parse collection env vars
420→  const envVars = parseEnvVars(collection.envVars);
421→
422→  for (const collectionTool of collection.tools) {
423→    const tool = collectionTool.tool;
424→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
425→
426→    // Avoid duplicates
427→    if (seenTools.has(toolKey)) continue;
428→    seenTools.add(toolKey);
429→
430→    const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
431→    tools[toolName] = createToolDefinition(tool, resolvedConfig, envVars);
432→  }
433→
434→  return tools;
435→}
