437→/**
438→ * Execute scenario using real agent with collection tools
439→ */
440→async function executeWithAgent(scenario: Scenario): Promise<{
441→  output: string;
442→  conversation: unknown[];
443→  usage: {
444→    inputTokens: number;
445→    outputTokens: number;
446→    totalTokens: number;
447→  };
448→  durationMs: number;
449→}> {
450→  const startTime = Date.now();
451→
452→  // Verify scenario has a collection
453→  if (!scenario.collectionId) {
454→    throw new ScenarioExecutionError('Scenario has no associated collection', 'NO_COLLECTION', {
455→      scenarioId: scenario.id,
456→    });
457→  }
458→
459→  // Fetch collection with tools
460→  const collection = await fetchCollectionWithTools(scenario.collectionId);
461→  if (!collection) {
462→    throw new ScenarioExecutionError(
463→      `Collection not found: ${scenario.collectionId}`,
464→      'COLLECTION_NOT_FOUND',
465→      { scenarioId: scenario.id, collectionId: scenario.collectionId }
466→    );
467→  }
468→
469→  if (collection.tools.length === 0) {
470→    throw new ScenarioExecutionError('Collection has no tools configured', 'NO_TOOLS', {
471→      scenarioId: scenario.id,
472→      collectionId: collection.id,
473→      collectionName: collection.name,
474→    });
475→  }
476→
477→  // Build tools from collection
478→  let tools: Record<string, ReturnType<typeof createToolDefinition>>;
479→  try {
480→    tools = buildCollectionTools(collection);
481→  } catch (err) {
482→    throw new ScenarioExecutionError(
483→      `Failed to build tools: ${err instanceof Error ? err.message : 'Unknown error'}`,
484→      'TOOL_BUILD_ERROR',
485→      { scenarioId: scenario.id, collectionId: collection.id, error: String(err) }
486→    );
487→  }
488→
489→  logScenarioEvent('tools_built', scenario.id, {
490→    toolCount: Object.keys(tools).length,
491→    toolNames: Object.keys(tools),
492→  });
493→
494→  // Build system prompt for scenario execution
495→  const systemPrompt = `You are an AI assistant tasked with completing the following scenario using the available tools.
496→
497→IMPORTANT: You must actually USE the tools to complete the task. Do not just describe what you would do - execute the tools.
498→
499→Available tools: ${Object.keys(tools).join(', ')}
500→
501→Complete the user's task to the best of your ability using the tools provided.`;
502→
503→  // Execute with generateText and multi-step tool loop
504→  const result = await (async () => {
505→    try {
506→      return await generateText({
507→        model: openai(DEFAULT_MODEL),
508→        messages: [
509→          { role: 'system', content: systemPrompt },
510→          { role: 'user', content: scenario.prompt },
511→        ],
512→        tools,
513→        stopWhen: stepCountIs(MAX_TOOL_STEPS),
514→      });
515→    } catch (err) {
516→      throw new ScenarioExecutionError(
517→        `AI execution failed: ${err instanceof Error ? err.message : 'Unknown error'}`,
518→        'EXECUTION_ERROR',
519→        {
520→          scenarioId: scenario.id,
521→          error: String(err),
522→          model: DEFAULT_MODEL,
523→          maxSteps: MAX_TOOL_STEPS,
524→        }
525→      );
526→    }
527→  })();
528→
529→  // Build conversation history from response
530→  const conversation: unknown[] = [{ role: 'user', content: scenario.prompt }];
531→
532→  // Add all steps to conversation
533→  for (const step of result.steps || []) {
534→    if (step.toolCalls && step.toolCalls.length > 0) {
535→      for (const toolCall of step.toolCalls) {
536→        conversation.push({
537→          role: 'assistant',
538→          toolCall: {
539→            id: toolCall.toolCallId,
540→            name: toolCall.toolName,
541→            // AI SDK v6 uses 'input' property for DynamicToolCall
542→            input: (toolCall as { input?: unknown }).input,
543→          },
544→        });
545→      }
546→    }
547→
548→    if (step.toolResults && step.toolResults.length > 0) {
549→      for (const toolResult of step.toolResults) {
550→        conversation.push({
551→          role: 'tool',
552→          toolCallId: toolResult.toolCallId,
553→          output: toolResult.output,
554→        });
555→      }
556→    }
557→
558→    if (step.text) {
559→      conversation.push({ role: 'assistant', content: step.text });
560→    }
561→  }
562→
563→  // Final assistant message
564→  if (result.text) {
565→    conversation.push({ role: 'assistant', content: result.text });
566→  }
567→
568→  const durationMs = Date.now() - startTime;
569→
570→  // Get token usage
571→  const usage = result.usage || { inputTokens: 0, outputTokens: 0, totalTokens: 0 };
572→
573→  logScenarioEvent('execution_complete', scenario.id, {
574→    durationMs,
575→    stepCount: result.steps?.length || 0,
576→    inputTokens: usage.inputTokens ?? 0,
577→    outputTokens: usage.outputTokens ?? 0,
578→    hasOutput: !!result.text,
579→  });
580→
581→  return {
582→    output: result.text || '[No output generated]',
583→    conversation,
584→    usage: {
585→      inputTokens: usage.inputTokens ?? 0,
586→      outputTokens: usage.outputTokens ?? 0,
587→      totalTokens: (usage.inputTokens ?? 0) + (usage.outputTokens ?? 0),
588→    },
589→    durationMs,
590→  };
591→}
