593→/**
594→ * Get user's current quota status
595→ */
596→export async function getQuotaStatus(
597→  userId: string
598→): Promise<{ used: number; limit: number; remaining: number; resetsAt: Date }> {
599→  const now = new Date();
600→  const tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
601→
602→  const quota = await prisma.scenarioQuota.findUnique({
603→    where: { userId },
604→  });
605→
606→  if (!quota) {
607→    return { used: 0, limit: 50, remaining: 50, resetsAt: tomorrow };
608→  }
609→
610→  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());
611→  const used = quota.lastResetAt < startOfDay ? 0 : quota.dailyUsed;
612→
613→  return {
614→    used,
615→    limit: quota.dailyLimit,
616→    remaining: quota.dailyLimit - used,
617→    resetsAt: tomorrow,
618→  };
619→}
