143→      ANTHROPIC: 'ANTHROPIC_API_KEY',
144→      GOOGLE: 'GOOGLE_API_KEY',
145→      GROQ: 'GROQ_API_KEY',
146→      MISTRAL: 'MISTRAL_API_KEY',
147→    };
148→    const keyName = providerKeyNames[agent.provider];
149→
150→    if (!keyName) {
151→      return NextResponse.json(
152→        { success: false, error: `Unsupported provider: ${agent.provider}` },
153→        { status: 400 }
154→      );
155→    }
156→
157→    let apiKey: string;
158→    let callerEnvVars: Record<string, string> | undefined;
159→
160→    if (isOwner) {
161→      // Owner: use stored encrypted keys
162→      const userApiKey = await prisma.userApiKey.findUnique({
163→        where: {
164→          userId_keyName: {
165→            userId: agent.userId,
166→            keyName,
167→          },
168→        },
169→      });
170→
171→      if (!userApiKey) {
172→        return NextResponse.json(
173→          {
174→            success: false,
175→            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→          },
177→          { status: 400 }
178→        );
179→      }
180→
181→      // Decrypt the API key
182→      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
184→    } else {
185→      // Non-owner accessing public agent: must provide their own credentials
186→      if (!parsed.data.providerApiKey) {
187→        return NextResponse.json(
188→          {
189→            success: false,
190→            error: 'Public agent access requires your own API key',
191→            details: {
192→              code: 'MISSING_PROVIDER_KEY',
193→              requiredProvider: agent.provider,
194→              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
195→            },
196→          },
197→          { status: 400 }
198→        );
199→      }
200→
201→      apiKey = parsed.data.providerApiKey;
202→      callerEnvVars = parsed.data.env || {};
203→
204→      // Check for required environment variables
205→      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
206→      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);
207→
208→      if (missingEnvVars.length > 0) {
209→        return NextResponse.json(
210→          {
211→            success: false,
212→            error: 'Missing required environment variables',
213→            details: {
214→              code: 'MISSING_ENV_VARS',
215→              missingVars: missingEnvVars.map((e) => ({
216→                name: e.name,
217→                description: e.description,
218→              })),
219→              hint: "Provide these variables in the 'env' field of your request",
220→            },
221→          },
222→          { status: 400 }
223→        );
224→      }
225→    }
226→
227→    // Get or create conversation
228→    let conversation = await prisma.conversation.findUnique({
229→      where: {
230→        agentId_slug: {
231→          agentId: agent.id,
232→          slug: conversationId,
233→        },
234→      },
235→    });
236→
237→    if (!conversation) {
238→      conversation = await prisma.conversation.create({
239→        data: {
240→          agentId: agent.id,
241→          slug: conversationId,
242→          title: parsed.data.message.slice(0, 100),
243→        },
244→      });
245→
246→      // Log activity for new conversation (fire-and-forget)
247→      if (agent.userId) {
248→        logActivity({
249→          userId: agent.userId,
250→          type: 'AGENT_CONVERSATION_STARTED',
251→          targetName: agent.name,
252→          targetType: 'agent',
253→          agentId: agent.id,
254→        });
255→      }
256→    }
257→
258→    // Fetch recent messages for context
259→    const recentMessages = await prisma.message.findMany({
260→      where: { conversationId: conversation.id },
261→      orderBy: { createdAt: 'desc' },
262→      take: agent.maxMessagesInContext,
263→    });
264→
265→    // Reverse to get chronological order
266→    recentMessages.reverse();
267→
268→    // Save user message
269→    await prisma.message.create({
270→      data: {
271→        conversationId: conversation.id,
272→        role: 'USER',
273→        content: parsed.data.message,
274→      },
275→    });
276→
277→    // Build AI SDK messages from conversation history
278→    const { streamText, stepCountIs } = await import('ai');
279→
280→    const messages: ModelMessage[] = [];
281→
282→    // Add system prompt if defined
283→    if (agent.systemPrompt) {
284→      messages.push({
285→        role: 'system',
286→        content: agent.systemPrompt,
287→      });
288→    }
289→
290→    // Build a set of tool call IDs that have corresponding tool results
291→    // This is needed because AI SDK requires every tool call to have a matching tool result
292→    const toolResultIds = new Set(
293→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
294→    );
295→
296→    // Add conversation history - properly format for AI SDK
297→    for (const msg of recentMessages) {
298→      if (msg.role === 'USER') {
299→        messages.push({ role: 'user', content: msg.content });
300→      } else if (msg.role === 'ASSISTANT') {
301→        // For assistant messages with tool calls, include ToolCallParts in content
302→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
303→          // Only include tool calls that have matching tool results
304→          // AI SDK fails if there's a tool call without a corresponding tool result
305→          const validToolCalls = (
306→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
307→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
308→
309→          if (validToolCalls.length > 0) {
310→            const toolCallParts = validToolCalls.map((tc) => ({
311→              type: 'tool-call' as const,
312→              toolCallId: tc.toolCallId,
313→              toolName: tc.toolName,
314→              input: tc.args,
315→            }));
316→            // Content includes text (if any) plus tool call parts
317→            const content: Array<
318→              | { type: 'text'; text: string }
319→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
320→            > = [];
321→            if (msg.content) {
322→              content.push({ type: 'text', text: msg.content });
323→            }
324→            content.push(...toolCallParts);
325→            messages.push({
326→              role: 'assistant',
327→              content,
328→            });
329→          } else {
330→            // All tool calls are missing results, just include text content
331→            messages.push({
332→              role: 'assistant',
333→              content: msg.content || '',
334→            });
335→          }
336→        } else {
337→          messages.push({
338→            role: 'assistant',
339→            content: msg.content,
340→          });
341→        }
342→      } else if (msg.role === 'TOOL') {
343→        // Tool results use the 'tool' role with content array
344→        messages.push({
345→          role: 'tool',
346→          content: [
347→            {
348→              type: 'tool-result' as const,
349→              toolCallId: msg.toolCallId || '',
350→              toolName: msg.toolName || '',
351→              output: {
352→                type: 'json' as const,
353→                value: msg.toolResult,
354→              },
355→            },
356→          ],
357→        });
358→      }
359→    }
360→
361→    // Add new user message
362→    messages.push({ role: 'user', content: parsed.data.message });
363→
364→    // Set up sandbox session if agent has sandbox enabled
365→    let sessionId: string | undefined;
366→    let _sandboxUrl: string | undefined;
367→    let _sandboxApiKey: string | undefined;
368→    if (agent.sandboxEnabled) {
369→      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
370→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
371→      if (!sandboxUrl) {
372→        return NextResponse.json(
373→          {
374→            success: false,
375→            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
376→          },
377→          { status: 502 }
378→        );
379→      }
380→      _sandboxUrl = sandboxUrl;
381→      _sandboxApiKey = sandboxApiKey;
382→      sessionId = `${agent.id}:${conversationId}`;
383→      try {
384→        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
385→      } catch (error) {
386→        console.error('[Sandbox] Failed to create session:', error);
387→        return NextResponse.json(
388→          {
389→            success: false,
390→            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
391→          },
392→          { status: 502 }
393→        );
394→      }
395→    }
396→
397→    // Build tools from agent configuration
398→    // Build tools - pass callerEnvVars if non-owner accessing public agent
399→    const tools = buildAgentTools(agent, callerEnvVars, sessionId, _sandboxUrl, _sandboxApiKey);
400→
401→    // Get the provider model
402→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
403→
404→    // Create SSE stream
405→    const stream = new ReadableStream({
406→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
407→      async start(controller) {
408→        const encoder = new TextEncoder();
409→
410→        const sendEvent = (event: string, data: unknown) => {
411→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
412→          controller.enqueue(encoder.encode(message));
413→        };
414→
415→        try {
416→          const startTime = Date.now();
417→          let fullContent = '';
418→          // Accumulate tool calls with their input args
419→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
420→            new Map();
421→          // Collect tool results to save AFTER assistant message (for correct chronological order)
422→          const pendingToolResults: Array<{
423→            toolCallId: string;
424→            toolName: string;
425→            output: unknown;
426→          }> = [];
427→          let inputTokens = 0;
428→          let outputTokens = 0;
429→
430→          // Stream the response with agentic loop control
431→          const result = await streamText({
432→            model,
433→            messages,
434→            tools,
435→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
436→            onChunk: async ({ chunk }) => {
437→              // Stream tool calls as they come in and capture their inputs
438→              if (chunk.type === 'tool-call') {
439→                const input = 'args' in chunk ? chunk.args : chunk.input;
440→
441→                // Log tool call for debugging
442→                console.log('[Agent] Tool call initiated:', {
443→                  toolName: chunk.toolName,
444→                  toolCallId: chunk.toolCallId,
445→                  input: JSON.stringify(input).slice(0, 500),
446→                });
447→
448→                // Store tool call with input for later persistence
449→                toolCallsMap.set(chunk.toolCallId, {
450→                  toolCallId: chunk.toolCallId,
451→                  toolName: chunk.toolName,
452→                  args: input,
453→                });
454→                sendEvent('tool_call', {
455→                  toolCallId: chunk.toolCallId,
456→                  toolName: chunk.toolName,
457→                  input,
458→                });
459→              }
460→            },
461→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
462→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
463→              // Capture tool calls from step finish (backup in case onChunk missed any)
464→              if (toolCalls && Array.isArray(toolCalls)) {
465→                for (const tc of toolCalls) {
466→                  if (!toolCallsMap.has(tc.toolCallId)) {
467→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
468→                    const args =
469→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
470→                    toolCallsMap.set(tc.toolCallId, {
471→                      toolCallId: tc.toolCallId,
472→                      toolName: tc.toolName,
473→                      args,
474→                    });
475→                  }
476→                }
477→              }
478→
479→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
480→              if (toolResults && toolResults.length > 0) {
481→                for (const tr of toolResults) {
482→                  // Check if this is an error result (AI SDK wraps errors in the output)
483→                  const isError =
484→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
485→
486→                  // Log tool results for debugging
487→                  if (isError) {
488→                    console.error('[Agent] Tool execution failed:', {
489→                      toolName: tr.toolName,
490→                      toolCallId: tr.toolCallId,
491→                      error: tr.output,
492→                    });
493→                  } else {
494→                    console.log('[Agent] Tool execution success:', {
495→                      toolName: tr.toolName,
496→                      toolCallId: tr.toolCallId,
497→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
498→                    });
499→                  }
500→
501→                  sendEvent('tool_result', {
502→                    toolCallId: tr.toolCallId,
503→                    output: tr.output,
504→                    isError,
505→                  });
506→
507→                  // Collect tool results to save after assistant message
508→                  pendingToolResults.push({
509→                    toolCallId: tr.toolCallId,
510→                    toolName: tr.toolName,
511→                    output: tr.output,
512→                  });
513→
514→                  // Track each tool call execution event
515→                  trackExecution({
516→                    eventType: 'tool_call',
517→                    source: 'agent_chat',
518→                    userId: authResult.userId ?? undefined,
519→                    apiKeyId: authResult.apiKeyId ?? undefined,
520→                    agentId: agent.id,
521→                    toolName: tr.toolName,
522→                    status: isError ? 'error' : 'success',
523→                  });
524→                }
525→              }
526→
527→              // Track token usage
528→              if (usage) {
529→                inputTokens += usage.inputTokens ?? 0;
530→                outputTokens += usage.outputTokens ?? 0;
531→              }
532→            },
533→          });
534→
535→          // Stream text chunks
536→          for await (const chunk of result.textStream) {
537→            fullContent += chunk;
538→            sendEvent('chunk', { type: 'text', text: chunk });
539→          }
540→
541→          // Get final response data
542→          const finalUsage = await result.usage;
543→
544→          // Convert tool calls map to array for storage
545→          const allToolCalls = Array.from(toolCallsMap.values());
546→
547→          // Update token counts from final usage
548→          if (finalUsage) {
549→            inputTokens = finalUsage.inputTokens ?? inputTokens;
550→            outputTokens = finalUsage.outputTokens ?? outputTokens;
551→          }
552→
553→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
554→          const assistantMessage = await prisma.message.create({
555→            data: {
556→              conversationId: conversation.id,
557→              role: 'ASSISTANT',
558→              content: fullContent,
559→              // Cast to Prisma-compatible JSON type
560→              toolCalls:
561→                allToolCalls.length > 0
562→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
563→                  : Prisma.JsonNull,
564→              inputTokens,
565→              outputTokens,
566→            },
567→          });
568→
569→          // Now save TOOL messages (after assistant, for correct chronological order)
570→          for (const tr of pendingToolResults) {
571→            await prisma.message.create({
572→              data: {
573→                conversationId: conversation.id,
574→                role: 'TOOL',
575→                content: JSON.stringify(tr.output),
576→                toolCallId: tr.toolCallId,
577→                toolName: tr.toolName,
578→                toolResult: tr.output as object,
579→              },
580→            });
581→          }
582→
583→          // Update conversation timestamp
584→          await prisma.conversation.update({
585→            where: { id: conversation.id },
586→            data: { updatedAt: new Date() },
587→          });
588→
589→          const executionTimeMs = Date.now() - startTime;
590→
591→          // Send token usage
592→          sendEvent('tokens', {
593→            inputTokens,
594→            outputTokens,
595→            totalTokens: inputTokens + outputTokens,
596→          });
597→
598→          // Send completion event
599→          sendEvent('complete', {
600→            messageId: assistantMessage.id,
601→            conversationId: conversation.id,
602→            executionTimeMs,
603→          });
604→
605→          // Track agent run execution event
606→          trackExecution({
607→            eventType: 'agent_run',
608→            source: 'agent_chat',
609→            userId: authResult.userId ?? undefined,
610→            apiKeyId: authResult.apiKeyId ?? undefined,
611→            agentId: agent.id,
612→            status: 'success',
613→            durationMs: executionTimeMs,
614→            tokensIn: inputTokens,
615→            tokensOut: outputTokens,
616→          });
617→
618→          // Track usage
619→          if (authResult.userId) {
620→            trackUsage({
621→              apiKeyId: authResult.apiKeyId ?? undefined,
622→              userId: authResult.userId,
623→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
624→              method: 'POST',
625→              statusCode: 200,
626→              latencyMs: executionTimeMs,
627→              resourceType: 'agent',
628→              resourceId: agentId,
629→              tokensIn: inputTokens,
630→              tokensOut: outputTokens,
631→              model: agent.modelId,
632→            });
633→          }
634→        } catch (error) {
635→          // Log detailed error for debugging
636→          console.error('[Agent] Conversation stream error:', {
637→            error: error instanceof Error ? error.message : String(error),
638→            stack: error instanceof Error ? error.stack : undefined,
639→            agentId: agent.id,
640→            conversationId: conversation.id,
641→          });
642→          sendEvent('error', {
643→            message: error instanceof Error ? error.message : 'Unknown error',
644→          });
645→
646→          // Track agent run error
647→          trackExecution({
648→            eventType: 'agent_run',
649→            source: 'agent_chat',
650→            userId: authResult.userId ?? undefined,
651→            apiKeyId: authResult.apiKeyId ?? undefined,
652→            agentId: agent.id,
653→            status: 'error',
654→            durationMs: Date.now() - startTime,
655→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
656→          });
657→
658→          // Track error
659→          if (authResult.userId) {
660→            trackUsage({
661→              apiKeyId: authResult.apiKeyId ?? undefined,
662→              userId: authResult.userId,
663→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
664→              method: 'POST',
665→              statusCode: 500,
666→              latencyMs: Date.now() - startTime,
667→              resourceType: 'agent',
668→              resourceId: agentId,
669→              errorCode: 'STREAM_ERROR',
670→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
671→            });
672→          }
673→        } finally {
674→          controller.close();
675→        }
676→      },
677→    });
678→
679→    return new NextResponse(stream, {
680→      headers: {
681→        'Content-Type': 'text/event-stream',
682→        'Cache-Control': 'no-cache',
683→        Connection: 'keep-alive',
684→      },
685→    });
686→  } catch (error) {
687→    console.error('Failed to process message:', error);
688→    return NextResponse.json(
689→      {
690→        success: false,
691→        error: error instanceof Error ? error.message : 'Failed to process message',
692→      },
693→      { status: 500 }
694→    );
695→  }
696→}
