698→/**
699→ * GET /api/agents/[id]/conversation/[conversationId]
700→ * Retrieve conversation history with pagination
701→ *
702→ * Query params:
703→ * - limit: Max messages to return (default: 50, max: 100)
704→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
705→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
706→ * - format: 'json' for full debug view (no pagination, includes agent info)
707→ *
708→ * Default behavior (no before/after): Returns the most recent messages
709→ * With before: Returns messages older than the timestamp (for scrolling up)
710→ * With after: Returns messages newer than the timestamp (for refreshing)
711→ */
712→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
713→  const { id: agentId, conversationId } = await context.params;
714→  const { searchParams } = new URL(request.url);
715→
716→  const format = searchParams.get('format');
717→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
718→  const before = searchParams.get('before');
719→  const after = searchParams.get('after');
720→
721→  try {
722→    // Fetch agent by ID with more details for JSON format
723→    const agent = await prisma.agent.findUnique({
724→      where: { id: agentId },
725→      select: {
726→        id: true,
727→        uid: true,
728→        name: true,
729→        provider: true,
730→        modelId: true,
731→        sandboxEnabled: true,
732→        executorType: true,
733→        executorConfig: true,
734→      },
735→    });
736→
737→    if (!agent) {
738→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
739→    }
740→
741→    // Fetch conversation
742→    const conversation = await prisma.conversation.findUnique({
743→      where: {
744→        agentId_slug: {
745→          agentId: agent.id,
746→          slug: conversationId,
747→        },
748→      },
749→    });
750→
751→    if (!conversation) {
752→      return NextResponse.json(
753→        { success: false, error: 'Conversation not found' },
754→        { status: 404 }
755→      );
756→    }
757→
758→    // For JSON format, return all messages with full details
759→    if (format === 'json') {
760→      const allMessages = await prisma.message.findMany({
761→        where: { conversationId: conversation.id },
762→        orderBy: { createdAt: 'asc' },
763→      });
764→
765→      const response = {
766→        _meta: {
767→          exportedAt: new Date().toISOString(),
768→          format: 'tpmjs-conversation-log',
769→          version: '1.0',
770→        },
771→        agent: {
772→          id: agent.id,
773→          uid: agent.uid,
774→          name: agent.name,
775→          provider: agent.provider,
776→          modelId: agent.modelId,
777→          executorType: agent.executorType,
778→          executorConfig: agent.executorConfig,
779→        },
780→        conversation: {
781→          id: conversation.id,
782→          slug: conversation.slug,
783→          title: conversation.title,
784→          createdAt: conversation.createdAt,
785→          updatedAt: conversation.updatedAt,
786→          messageCount: allMessages.length,
787→        },
788→        messages: allMessages.map((m) => ({
789→          id: m.id,
790→          role: m.role,
791→          content: m.content,
792→          toolCalls: m.toolCalls,
793→          toolCallId: m.toolCallId,
794→          toolName: m.toolName,
795→          toolResult: m.toolResult,
796→          inputTokens: m.inputTokens,
797→          outputTokens: m.outputTokens,
798→          createdAt: m.createdAt,
799→        })),
800→        stats: {
801→          totalMessages: allMessages.length,
802→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
803→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
804→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
805→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
806→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
807→        },
808→      };
809→
810→      // Return pretty-printed JSON with proper content type
811→      return new NextResponse(JSON.stringify(response, null, 2), {
812→        headers: {
813→          'Content-Type': 'application/json',
814→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
815→        },
816→      });
817→    }
818→
819→    // Standard paginated response
820→    const whereClause: {
821→      conversationId: string;
822→      createdAt?: { lt?: Date; gt?: Date };
823→    } = { conversationId: conversation.id };
824→
825→    if (before) {
826→      whereClause.createdAt = { lt: new Date(before) };
827→    } else if (after) {
828→      whereClause.createdAt = { gt: new Date(after) };
829→    }
830→
831→    // Determine fetch order:
832→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
833→    // - "after": Fetch asc (oldest first) to get messages after the cursor
834→    const shouldFetchDesc = !after;
835→
836→    // Fetch messages
837→    const messages = await prisma.message.findMany({
838→      where: whereClause,
839→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
840→      take: limit + 1,
841→    });
842→
843→    const hasMore = messages.length > limit;
844→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
845→
846→    // Reverse if we fetched in desc order to maintain chronological order
847→    if (shouldFetchDesc) {
848→      paginatedMessages = paginatedMessages.reverse();
849→    }
850→
851→    const mappedMessages = paginatedMessages.map((m) => ({
852→      id: m.id,
853→      role: m.role,
854→      content: m.content,
855→      toolCalls: m.toolCalls,
856→      toolCallId: m.toolCallId,
857→      toolName: m.toolName,
858→      toolResult: m.toolResult,
859→      inputTokens: m.inputTokens,
860→      outputTokens: m.outputTokens,
861→      createdAt: m.createdAt,
862→    }));
863→
864→    return NextResponse.json({
865→      success: true,
866→      data: {
867→        id: conversation.id,
868→        slug: conversation.slug,
869→        title: conversation.title,
870→        createdAt: conversation.createdAt,
871→        updatedAt: conversation.updatedAt,
872→        messages: mappedMessages,
873→      },
874→      pagination: {
875→        limit,
876→        hasMore,
877→        ...(before && { before }),
878→        ...(after && { after }),
879→      },
880→    });
881→  } catch (error) {
882→    console.error('Failed to fetch conversation:', error);
883→    return NextResponse.json(
884→      { success: false, error: 'Failed to fetch conversation' },
885→      { status: 500 }
886→    );
887→  }
888→}
889→
890→/**
891→ * DELETE /api/agents/[id]/conversation/[conversationId]
892→ * Delete a conversation
893→ */
894→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
895→  const { id: agentId, conversationId } = await context.params;
896→
897→  try {
898→    // Fetch agent by ID (include sandboxEnabled for cleanup)
899→    const agent = await prisma.agent.findUnique({
900→      where: { id: agentId },
901→      select: { id: true, sandboxEnabled: true },
902→    });
903→
904→    if (!agent) {
905→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
906→    }
907→
908→    // Destroy sandbox session if applicable (fire-and-forget)
909→    if (agent.sandboxEnabled) {
910→      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
911→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
912→      if (sandboxUrl) {
913→        const sessionId = `${agent.id}:${conversationId}`;
914→        destroySandboxSession(sandboxUrl, sandboxApiKey, sessionId).catch(() => {});
915→      }
916→    }
917→
918→    // Delete conversation (messages cascade)
919→    await prisma.conversation.deleteMany({
920→      where: {
921→        agentId: agent.id,
922→        slug: conversationId,
923→      },
924→    });
925→
926→    return NextResponse.json({
927→      success: true,
928→      data: { deleted: true },
929→    });
930→  } catch (error) {
931→    console.error('Failed to delete conversation:', error);
932→    return NextResponse.json(
933→      { success: false, error: 'Failed to delete conversation' },
934→      { status: 500 }
935→    );
936→  }
937→}
