 452→                setToolCalls((prev) =>
 453→                  prev.map((tc) =>
 454→                    tc.toolCallId === data.toolCallId
 455→                      ? {
 456→                          ...tc,
 457→                          output: data.output,
 458→                          status: data.isError ? ('error' as const) : ('success' as const),
 459→                        }
 460→                      : tc
 461→                  )
 462→                );
 463→                break;
 464→              case 'complete':
 465→                // Refresh messages
 466→                await fetchMessages();
 467→                setStreamingContent('');
 468→                setToolCalls([]);
 469→                break;
 470→              case 'error':
 471→                throw new Error(data.message);
 472→            }
 473→          }
 474→        }
 475→      }
 476→    } catch (err) {
 477→      console.error('Failed to send message:', err);
 478→      setError(err instanceof Error ? err.message : 'Failed to send message');
 479→      // Remove optimistic message on error
 480→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
 481→    } finally {
 482→      setIsSending(false);
 483→      setStreamingContent('');
 484→      inputRef.current?.focus();
 485→    }
 486→  };
 487→
 488→  const handleKeyDown = (e: React.KeyboardEvent) => {
 489→    if (e.key === 'Enter' && !e.shiftKey) {
 490→      e.preventDefault();
 491→      handleSend();
 492→    }
 493→  };
