 851→                        if (message.toolResult) return message.toolResult;
 852→                        try {
 853→                          return JSON.parse(message.content || '{}');
 854→                        } catch {
 855→                          return { result: message.content };
 856→                        }
 857→                      };
 858→
 859→                      // Build a lookup map for tool call inputs from ASSISTANT messages
 860→                      // This allows us to show the input args when rendering TOOL messages
 861→                      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Helper in virtuoso render callback
 862→                      const getToolCallInput = (toolCallId: string): unknown => {
 863→                        for (const msg of messages) {
 864→                          if (msg.role === 'ASSISTANT' && msg.toolCalls) {
 865→                            const tc = msg.toolCalls.find((t) => t.toolCallId === toolCallId);
