 867→                          }
 868→                        }
 869→                        return undefined;
 870→                      };
 871→
 872→                      // Check if a tool call has a corresponding TOOL message (meaning it completed)
 873→                      const hasToolResult = (toolCallId: string): boolean => {
 874→                        return messages.some(
 875→                          (m) => m.role === 'TOOL' && m.toolCallId === toolCallId
 876→                        );
 877→                      };
 878→
 879→                      // Detect if a tool result is an error
 880→                      const isToolError = (output: unknown): boolean => {
 881→                        if (output && typeof output === 'object' && 'error' in output) return true;
 882→                        return false;
 883→                      };
 884→
 885→                      return (
 886→                        <div className="px-4 py-2">
 887→                          {/* TOOL message - shows the result of a tool call */}
 888→                          {message.role === 'TOOL' && (
 889→                            <div className="flex justify-start">
 890→                              <div className="max-w-[80%]">
 891→                                <ToolCallCard
 892→                                  toolCall={{
 893→                                    toolCallId: message.toolCallId || message.id,
 894→                                    toolName: message.toolName || 'Unknown Tool',
 895→                                    input: getToolCallInput(message.toolCallId || ''),
 896→                                    output: getToolOutput(),
 897→                                    status: isToolError(getToolOutput()) ? 'error' : 'success',
 898→                                  }}
 899→                                  isExpanded={expandedToolCalls.has(
 900→                                    message.toolCallId || message.id
 901→                                  )}
 902→                                  onToggle={() => toggleToolCall(message.toolCallId || message.id)}
 903→                                />
 904→                              </div>
 905→                            </div>
 906→                          )}
 907→
 908→                          {/* USER message */}
 909→                          {message.role === 'USER' && (
 910→                            <div className="flex justify-end">
 911→                              <div className="max-w-[80%] rounded-lg p-4 bg-primary text-primary-foreground">
 912→                                <div className="text-sm whitespace-pre-wrap">{message.content}</div>
 913→                              </div>
 914→                            </div>
 915→                          )}
 916→
 917→                          {/* ASSISTANT message - may contain text and/or tool calls */}
 918→                          {message.role === 'ASSISTANT' && (
 919→                            <div className="space-y-2">
 920→                              {/* Assistant text content */}
 921→                              {message.content && (
 922→                                <div className="flex justify-start">
 923→                                  <div className="max-w-[80%] rounded-lg p-4 bg-surface-secondary">
 924→                                    <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
 925→                                      <Streamdown>{message.content}</Streamdown>
 926→                                    </div>
 927→                                    {/* Token usage for debugging */}
 928→                                    {(message.inputTokens || message.outputTokens) && (
 929→                                      <div className="mt-2 pt-2 border-t border-border/50 text-[10px] text-foreground-tertiary font-mono">
 930→                                        {message.inputTokens && (
 931→                                          <span>In: {message.inputTokens}</span>
 932→                                        )}
 933→                                        {message.inputTokens && message.outputTokens && (
 934→                                          <span> • </span>
 935→                                        )}
 936→                                        {message.outputTokens && (
 937→                                          <span>Out: {message.outputTokens}</span>
 938→                                        )}
 939→                                      </div>
 940→                                    )}
 941→                                  </div>
 942→                                </div>
 943→                              )}
 944→
 945→                              {/* Show tool calls from this assistant message that don't have results yet */}
 946→                              {message.toolCalls
 947→                                ?.filter((tc) => !hasToolResult(tc.toolCallId))
 948→                                .map((tc) => (
 949→                                  <div key={tc.toolCallId} className="flex justify-start">
 950→                                    <div className="max-w-[80%]">
 951→                                      <ToolCallCard
 952→                                        toolCall={{
 953→                                          toolCallId: tc.toolCallId,
 954→                                          toolName: tc.toolName,
 955→                                          input: tc.args,
 956→                                          status: 'pending',
 957→                                        }}
 958→                                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
 959→                                        onToggle={() => toggleToolCall(tc.toolCallId)}
 960→                                      />
 961→                                    </div>
 962→                                  </div>
 963→                                ))}
 964→                            </div>
 965→                          )}
 966→                        </div>
 967→                      );
 968→                    }}
 969→                  />
 970→                )}
 971→              </div>
 972→
 973→              {/* Error Message */}
 974→              {error && (
