 992→                    style={{
 993→                      height: 'auto',
 994→                      minHeight: '48px',
 995→                    }}
 996→                    onInput={(e) => {
 997→                      const target = e.target as HTMLTextAreaElement;
 998→                      target.style.height = 'auto';
 999→                      target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
1000→                    }}
1001→                  />
1002→                  <Button onClick={handleSend} disabled={isSending || !input.trim()}>
1003→                    <Icon icon="send" size="sm" />
1004→                  </Button>
1005→                </div>
1006→                <p className="text-xs text-foreground-tertiary mt-2">
1007→                  Press Enter to send, Shift+Enter for new line
1008→                </p>
1009→              </div>
1010→            </>
1011→          )}
1012→        </div>
1013→      </div>
1014→    </div>
1015→  );
1016→}
