138→          <Icon
139→            icon={statusIcons[effectiveStatus]}
140→            size="xs"
141→            className={effectiveStatus === 'running' ? 'animate-spin' : ''}
142→          />
143→        </div>
144→        <div className="flex-1 text-left min-w-0">
145→          <div className="flex items-center gap-2">
146→            <span className="text-foreground font-semibold truncate">{toolCall.toolName}</span>
147→            <span className="text-foreground-tertiary text-[10px]">
