159→        </div>
160→        <Icon
161→          icon="chevronRight"
162→          size="xs"
163→          className={`text-foreground-tertiary transition-transform flex-shrink-0 ${isExpanded ? 'rotate-90' : ''}`}
164→        />
165→      </Button>
166→
167→      {/* expanded content */}
168→      {isExpanded && (
169→        <div className="border-t border-dashed border-border">
170→          {/* input */}
171→          {toolCall.input !== undefined && toolCall.input !== null ? (
172→            <div className="p-3 border-b border-dashed border-border/50">
173→              <div className="flex items-center gap-2 mb-2">
174→                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
175→                  input
176→                </span>
177→                <div className="flex-1 h-px bg-border/50" />
178→              </div>
179→              <pre className="text-[11px] text-foreground-secondary overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto">
180→                {formatJson(toolCall.input)}
181→              </pre>
182→            </div>
183→          ) : null}
184→
185→          {/* error message */}
186→          {hasError && errorMessage && (
187→            <div className="p-3 bg-error/10 border-b border-dashed border-error/20">
188→              <div className="flex items-center gap-2 mb-2">
189→                <Icon icon="alertCircle" size="xs" className="text-error" />
190→                <span className="text-[10px] uppercase tracking-wider text-error font-semibold">
191→                  error
192→                </span>
193→              </div>
194→              <p className="text-[11px] text-error">{errorMessage}</p>
195→            </div>
196→          )}
197→
198→          {/* output */}
199→          {toolCall.output !== undefined && toolCall.output !== null ? (
200→            <div className="p-3">
201→              <div className="flex items-center gap-2 mb-2">
202→                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
203→                  {hasError ? 'full response' : 'output'}
204→                </span>
205→                <div className="flex-1 h-px bg-border/50" />
206→              </div>
207→              <pre
208→                className={`text-[11px] overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto ${hasError ? 'text-error' : 'text-success'}`}
209→              >
210→                {formatJson(toolCall.output)}
211→              </pre>
212→            </div>
213→          ) : null}
214→
215→          {/* running indicator */}
216→          {toolCall.status === 'running' && !toolCall.output && (
217→            <div className="p-3 flex items-center gap-2 text-foreground-tertiary">
218→              <Icon icon="loader" size="xs" className="animate-spin" />
