371→
372→  const handleSend = async () => {
373→    if (!input.trim() || !agent || isSending) return;
374→
375→    const messageContent = input.trim();
376→    setInput('');
377→    setIsSending(true);
378→    setStreamingContent('');
379→    setError(null);
380→    setToolCalls([]);
381→
382→    const conversationId = activeConversationId || chatId;
383→
384→    // Optimistically add user message
385→    const userMessage: Message = {
386→      id: `temp-${Date.now()}`,
387→      role: 'USER',
388→      content: messageContent,
389→      createdAt: new Date().toISOString(),
390→    };
391→    setMessages((prev) => [...prev, userMessage]);
392→
393→    try {
394→      const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
395→        method: 'POST',
396→        headers: { 'Content-Type': 'application/json' },
397→        body: JSON.stringify({ message: messageContent }),
398→      });
399→
400→      if (!response.ok) {
401→        const errorData = await response.json();
402→        throw new Error(errorData.error || 'Failed to send message');
403→      }
404→
405→      // Handle SSE stream
406→      const reader = response.body?.getReader();
407→      if (!reader) throw new Error('No response body');
408→
409→      const decoder = new TextDecoder();
410→      let buffer = '';
411→
412→      while (true) {
413→        const { done, value } = await reader.read();
414→        if (done) break;
415→
416→        buffer += decoder.decode(value, { stream: true });
417→
418→        // Parse SSE events
419→        const lines = buffer.split('\n');
420→        buffer = lines.pop() || '';
421→
422→        let eventType = '';
423→        for (const line of lines) {
424→          if (line.startsWith('event: ')) {
425→            eventType = line.slice(7);
426→          } else if (line.startsWith('data: ')) {
427→            const data = JSON.parse(line.slice(6));
428→
429→            switch (eventType) {
430→              case 'chunk':
431→                setStreamingContent((prev) => prev + data.text);
432→                break;
433→              case 'tool_call':
434→                setToolCalls((prev) => [
435→                  ...prev,
436→                  {
437→                    toolCallId: data.toolCallId,
438→                    toolName: data.toolName,
439→                    input: data.input,
440→                    status: 'running',
441→                  },
442→                ]);
443→                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
444→                break;
445→              case 'tool_result':
446→                setToolCalls((prev) =>
447→                  prev.map((tc) =>
448→                    tc.toolCallId === data.toolCallId
449→                      ? { ...tc, output: data.output, status: 'success' as const }
450→                      : tc
451→                  )
452→                );
453→                break;
454→              case 'complete':
455→                await fetchMessages();
456→                await fetchConversations();
457→                setStreamingContent('');
458→                setToolCalls([]);
459→                break;
460→              case 'error':
461→                throw new Error(data.message);
462→            }
463→          }
464→        }
465→      }
466→    } catch (err) {
467→      console.error('Failed to send message:', err);
468→      setError(err instanceof Error ? err.message : 'Failed to send message');
469→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
470→    } finally {
471→      setIsSending(false);
472→      setStreamingContent('');
473→      inputRef.current?.focus();
474→    }
475→  };
476→
477→  const handleKeyDown = (e: React.KeyboardEvent) => {
