665→
666→            {(() => {
667→              // Build a map of toolCallId -> tool result from TOOL messages
668→              const toolResultsMap = new Map<string, unknown>();
669→              for (const msg of messages) {
670→                if (msg.role === 'TOOL' && msg.toolCallId) {
671→                  let output: unknown;
672→                  if (msg.toolResult) {
673→                    output = msg.toolResult;
674→                  } else {
675→                    try {
676→                      output = JSON.parse(msg.content || '{}');
677→                    } catch {
678→                      output = { result: msg.content };
679→                    }
680→                  }
681→                  toolResultsMap.set(msg.toolCallId, output);
682→                }
683→              }
684→
685→              return messages.map((message) => {
686→                const hasEmbeddedToolCalls =
687→                  message.role === 'ASSISTANT' &&
688→                  message.toolCalls &&
689→                  Array.isArray(message.toolCalls) &&
690→                  message.toolCalls.length > 0;
691→
692→                return (
693→                  <div key={message.id} className="space-y-2">
694→                    {/* Render embedded tool calls from ASSISTANT messages */}
695→                    {hasEmbeddedToolCalls && (
696→                      <div className="space-y-2">
697→                        {message.toolCalls?.map((tc) => {
698→                          const toolOutput = toolResultsMap.get(tc.toolCallId);
699→                          const hasOutput = toolOutput !== undefined;
700→
701→                          return (
702→                            <div key={tc.toolCallId} className="flex justify-start">
703→                              <div className="max-w-[85%]">
704→                                <ToolCallCard
705→                                  toolCall={{
706→                                    toolCallId: tc.toolCallId,
707→                                    toolName: tc.toolName,
708→                                    input: tc.args,
709→                                    output: toolOutput,
710→                                    status: hasOutput ? 'success' : 'pending',
711→                                  }}
712→                                  isExpanded={expandedToolCalls.has(tc.toolCallId)}
713→                                  onToggle={() => toggleToolCall(tc.toolCallId)}
714→                                />
715→                              </div>
716→                            </div>
717→                          );
718→                        })}
719→                      </div>
720→                    )}
721→
722→                    {/* Render the message content - skip TOOL messages */}
723→                    {message.role !== 'TOOL' && (
724→                      <div
725→                        className={`flex ${message.role === 'USER' ? 'justify-end' : 'justify-start'}`}
726→                      >
727→                        <div
728→                          className={`max-w-[85%] rounded-lg p-4 ${
729→                            message.role === 'USER'
730→                              ? 'bg-primary text-primary-foreground'
731→                              : 'bg-surface text-foreground border border-dashed border-border'
732→                          }`}
733→                        >
734→                          {message.role === 'USER' ? (
735→                            <div className="text-sm whitespace-pre-wrap">{message.content}</div>
736→                          ) : (
737→                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
738→                              <Streamdown>{message.content}</Streamdown>
739→                            </div>
740→                          )}
741→                        </div>
742→                      </div>
743→                    )}
744→                  </div>
745→                );
746→              });
747→            })()}
748→
749→            {/* Live tool calls during streaming */}
750→            {toolCalls.length > 0 && (
751→              <div className="space-y-2">
752→                {toolCalls.map((tc) => (
753→                  <div key={tc.toolCallId} className="flex justify-start">
754→                    <div className="max-w-[85%]">
755→                      <ToolCallCard
756→                        toolCall={tc}
757→                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
758→                        onToggle={() => toggleToolCall(tc.toolCallId)}
759→                      />
760→                    </div>
761→                  </div>
762→                ))}
763→              </div>
764→            )}
765→
766→            {streamingContent && (
767→              <div className="flex justify-start">
768→                <div className="max-w-[85%] rounded-lg p-4 bg-surface border border-dashed border-border">
769→                  <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
770→                    <Streamdown>{streamingContent}</Streamdown>
771→                  </div>
772→                  <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
773→                </div>
774→              </div>
775→            )}
776→
777→            {isSending && !streamingContent && toolCalls.length === 0 && (
778→              <div className="flex justify-start">
779→                <div className="rounded-lg p-4 bg-surface border border-dashed border-border">
780→                  <div className="flex items-center gap-2 text-foreground-secondary">
781→                    <Icon icon="loader" size="sm" className="animate-spin" />
782→                    <span className="text-sm font-mono lowercase">thinking...</span>
783→                  </div>
784→                </div>
785→              </div>
786→            )}
787→
788→            <div ref={messagesEndRef} />
789→          </div>
790→
791→          {/* Error Message */}
792→          {error && (
793→            <div className="px-4 py-2 bg-error/10 border-t border-dashed border-error/20">
794→              <p className="text-sm text-error font-mono">{error}</p>
795→            </div>
796→          )}
797→
798→          {/* Input Area */}
799→          <div className="border-t border-dashed border-border p-4 bg-surface">
800→            <div className="flex items-end gap-2">
801→              <Textarea
802→                ref={inputRef}
803→                value={input}
804→                onChange={(e) => setInput(e.target.value)}
805→                onKeyDown={handleKeyDown}
806→                placeholder="Type a message..."
807→                rows={1}
808→                resize="none"
809→                className="flex-1 min-h-[48px] max-h-[200px] font-mono"
810→                style={{
811→                  height: 'auto',
812→                  minHeight: '48px',
