826→            </p>
827→          </div>
828→        </div>
829→
830→        {/* Tools Panel */}
831→        <ChatToolsPanel
832→          tools={agent.tools}
833→          collections={agent.collections}
834→          isOpen={showToolsPanel}
835→          onClose={() => setShowToolsPanel(false)}
836→          onToolClick={setSelectedTool}
837→        />
