844→            isOpen={showSandboxLogs}
845→            onClose={() => setShowSandboxLogs(false)}
846→          />
847→        )}
848→      </div>
849→
850→      {/* Tool Details Modal */}
851→      <ToolDetailsModal
852→        tool={selectedTool}
853→        open={!!selectedTool}
