856→
857→      {/* Settings Drawer */}
858→      <ChatSettingsDrawer
859→        open={showSettings}
860→        onClose={() => setShowSettings(false)}
861→        agentId={agent.id}
862→        settings={{
863→          name: agent.name,
864→          provider: agent.provider,
865→          modelId: agent.modelId,
866→          systemPrompt: agent.systemPrompt,
867→          temperature: agent.temperature,
868→          maxToolCallsPerTurn: agent.maxToolCallsPerTurn,
