**SSE Stream Processing** (lines 372-486 in dashboard version, 374-486 in public version):
```typescript
const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ message: messageContent }),
});

// Handle SSE stream
const reader = response.body?.getReader();
const decoder = new TextDecoder();
let buffer = '';

while (true) {
  const { done, value } = await reader.read();
  if (done) break;

  buffer += decoder.decode(value, { stream: true });

  // Parse SSE events
  const lines = buffer.split('\n');
  buffer = lines.pop() || '';

  let eventType = '';
  for (const line of lines) {
    if (line.startsWith('event: ')) {
      eventType = line.slice(7);
    } else if (line.startsWith('data: ')) {
      const data = JSON.parse(line.slice(6));

      switch (eventType) {
        case 'chunk':
          setStreamingContent((prev) => prev + data.text);
          break;
        case 'tool_call':
          setToolCalls((prev) => [...prev, {...}]);
          break;
        case 'tool_result':
          setToolCalls((prev) => prev.map(...));
          break;
        case 'complete':
          await fetchMessages();
          break;
        case 'error':
          throw new Error(data.message);
      }
    }
  }
}
```

**SSE Event Types Handled**:
- `chunk` - Text content from the model (streams progressively)
