389→      createdAt: new Date().toISOString(),
390→    };
391→    setMessages((prev) => [...prev, userMessage]);
392→
393→    try {
394→      const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
395→        method: 'POST',
396→        headers: { 'Content-Type': 'application/json' },
397→        body: JSON.stringify({ message: messageContent }),
398→      });
399→
400→      if (!response.ok) {
401→        const errorData = await response.json();
402→        throw new Error(errorData.error || 'Failed to send message');
403→      }
404→
405→      // Handle SSE stream
406→      const reader = response.body?.getReader();
407→      if (!reader) throw new Error('No response body');
408→
409→      const decoder = new TextDecoder();
410→      let buffer = '';
411→
412→      while (true) {
413→        const { done, value } = await reader.read();
414→        if (done) break;
415→
416→        buffer += decoder.decode(value, { stream: true });
417→
418→        // Parse SSE events
419→        const lines = buffer.split('\n');
420→        buffer = lines.pop() || '';
421→
422→        let eventType = '';
423→        for (const line of lines) {
424→          if (line.startsWith('event: ')) {
425→            eventType = line.slice(7);
426→          } else if (line.startsWith('data: ')) {
427→            const data = JSON.parse(line.slice(6));
428→
429→            switch (eventType) {
430→              case 'chunk':
431→                setStreamingContent((prev) => prev + data.text);
432→                break;
433→              case 'tool_call':
434→                setToolCalls((prev) => [
435→                  ...prev,
436→                  {
437→                    toolCallId: data.toolCallId,
438→                    toolName: data.toolName,
439→                    input: data.input,
440→                    status: 'running',
441→                  },
442→                ]);
443→                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
444→                break;
445→              case 'tool_result':
446→                setToolCalls((prev) =>
447→                  prev.map((tc) =>
448→                    tc.toolCallId === data.toolCallId
449→                      ? { ...tc, output: data.output, status: 'success' as const }
450→                      : tc
451→                  )
452→                );
453→                break;
454→              case 'complete':
455→                await fetchMessages();
456→                await fetchConversations();
457→                setStreamingContent('');
458→                setToolCalls([]);
459→                break;
460→              case 'error':
461→                throw new Error(data.message);
462→            }
463→          }
464→        }
465→      }
466→    } catch (err) {
467→      console.error('Failed to send message:', err);
468→      setError(err instanceof Error ? err.message : 'Failed to send message');
469→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
470→    } finally {
471→      setIsSending(false);
472→      setStreamingContent('');
473→      inputRef.current?.focus();
474→    }
475→  };
476→
477→  const handleKeyDown = (e: React.KeyboardEvent) => {
478→    if (e.key === 'Enter' && !e.shiftKey) {
479→      e.preventDefault();
480→      handleSend();
481→    }
482→  };
483→
484→  const startNewConversation = () => {
485→    const newId = generateConversationId();
486→    router.push(`/dashboard/agents/${agentId}/chat/${newId}`);
487→  };
488→
489→  const handleSettingsChange = (newSettings: AgentSettings) => {
490→    if (agent) {
491→      setAgent({
492→        ...agent,
493→        ...newSettings,
494→      });
495→    }
496→  };
497→
498→  if (isLoading) {
499→    return (
500→      <DashboardLayout
501→        title="Loading..."
502→        showBackButton
503→        backUrl={`/dashboard/agents/${agentId}`}
504→        fullHeight
505→      >
506→        <div className="flex items-center justify-center h-full">
507→          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
508→        </div>
509→      </DashboardLayout>
510→    );
511→  }
512→
513→  if (error && !agent) {
514→    return (
515→      <DashboardLayout title="Error" showBackButton backUrl="/dashboard/agents" fullHeight>
516→        <div className="flex items-center justify-center h-full">
517→          <div className="text-center">
518→            <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
519→            <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
520→            <p className="text-foreground-secondary mb-4">{error}</p>
521→            <Link href="/dashboard/agents">
522→              <Button>Back to Agents</Button>
523→            </Link>
524→          </div>
525→        </div>
526→      </DashboardLayout>
527→    );
528→  }
529→
530→  if (!agent) {
531→    return (
532→      <DashboardLayout
533→        title="Loading..."
534→        showBackButton
535→        backUrl={`/dashboard/agents/${agentId}`}
536→        fullHeight
537→      >
538→        <div className="flex items-center justify-center h-full">
539→          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
540→        </div>
541→      </DashboardLayout>
542→    );
543→  }
544→
545→  return (
546→    <DashboardLayout
547→      title={agent.name}
548→      subtitle={`${PROVIDER_DISPLAY_NAMES[agent.provider]} / ${agent.modelId}`}
549→      showBackButton
550→      backUrl={`/dashboard/agents/${agent.id}`}
551→      fullHeight
552→      actions={
553→        <div className="flex items-center gap-2">
554→          <Button
555→            variant="ghost"
556→            size="sm"
557→            onClick={() => setShowToolsPanel(!showToolsPanel)}
558→            title={showToolsPanel ? 'Hide tools panel' : 'Show tools panel'}
559→            className={showToolsPanel ? 'bg-primary/10 text-primary' : ''}
560→          >
561→            <Icon icon="puzzle" size="xs" className="mr-1.5" />
562→            <span className="hidden sm:inline">Tools</span>
563→            {agent.tools.length > 0 && (
564→              <Badge variant="secondary" className="ml-1.5 text-[10px]">
565→                {agent.tools.length}
566→              </Badge>
567→            )}
568→          </Button>
569→          {agent.sandboxEnabled && (
570→            <Button
571→              variant="ghost"
572→              size="sm"
573→              onClick={() => setShowSandboxLogs(!showSandboxLogs)}
574→              title={showSandboxLogs ? 'Hide sandbox logs' : 'Show sandbox logs'}
575→              className={showSandboxLogs ? 'bg-primary/10 text-primary' : ''}
576→            >
577→              <Icon icon="terminal" size="xs" className="mr-1.5" />
578→              <span className="hidden sm:inline">Sandbox</span>
579→            </Button>
580→          )}
581→          <Button
582→            variant="ghost"
583→            size="sm"
584→            onClick={() => setShowSettings(true)}
585→            title="Agent settings"
586→          >
587→            <Icon icon="edit" size="xs" className="mr-1.5" />
588→            <span className="hidden sm:inline">Settings</span>
589→          </Button>
590→          <Button
591→            variant="ghost"
592→            size="sm"
593→            onClick={() => {
594→              window.open(
595→                `/api/agents/${agentId}/conversation/${activeConversationId}?format=json`,
596→                '_blank'
597→              );
598→            }}
599→            title="View conversation as JSON"
600→          >
601→            <Icon icon="terminal" size="xs" />
602→          </Button>
603→          <Button variant="outline" size="sm" onClick={startNewConversation}>
604→            <Icon icon="plus" size="xs" className="mr-1.5" />
605→            New Chat
606→          </Button>
607→        </div>
608→      }
609→    >
610→      <div className="flex h-full overflow-hidden">
611→        {/* Conversations Sidebar */}
612→        <div className="w-56 border-r border-dashed border-border flex flex-col bg-surface hidden md:flex">
613→          <div className="p-3 border-b border-dashed border-border">
614→            <span className="font-mono text-xs text-foreground-tertiary lowercase">
615→              conversations
616→            </span>
617→          </div>
618→          <div className="flex-1 overflow-y-auto p-2">
619→            {conversations.length === 0 ? (
620→              <p className="text-xs text-foreground-tertiary text-center py-4 font-mono">
621→                no conversations yet
622→              </p>
623→            ) : (
624→              conversations.map((conv) => (
625→                <button
626→                  type="button"
627→                  key={conv.id}
628→                  onClick={() => handleSelectConversation(conv.slug)}
629→                  className={`w-full text-left p-2 mb-1 rounded border border-transparent transition-colors ${
630→                    chatId === conv.slug
631→                      ? 'bg-primary/10 border-primary/20 text-primary'
632→                      : 'text-foreground-secondary hover:bg-surface-secondary hover:border-border'
633→                  }`}
634→                >
635→                  <p className="text-sm font-medium truncate">{conv.title || 'Untitled Chat'}</p>
636→                  <p className="text-[10px] text-foreground-tertiary font-mono mt-0.5">
637→                    {conv.messageCount} messages
638→                  </p>
639→                </button>
640→              ))
641→            )}
642→          </div>
643→        </div>
644→
645→        {/* Chat Area */}
646→        <div className="flex-1 flex flex-col min-w-0">
647→          {/* Messages */}
648→          <div className="flex-1 overflow-y-auto p-4 space-y-4">
649→            {messages.length === 0 && !streamingContent && (
650→              <div className="flex items-center justify-center h-full">
651→                <fieldset className="border border-dashed border-border p-8 max-w-md text-center">
652→                  <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
653→                    new conversation
654→                  </legend>
655→                  <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
656→                    <Icon icon="message" size="lg" className="text-primary" />
657→                  </div>
658→                  <h3 className="font-mono text-foreground mb-2 lowercase">start chatting</h3>
659→                  <p className="text-sm text-foreground-secondary">
660→                    Send a message to start a conversation with {agent.name}.
661→                  </p>
662→                </fieldset>
663→              </div>
664→            )}
665→
666→            {(() => {
667→              // Build a map of toolCallId -> tool result from TOOL messages
668→              const toolResultsMap = new Map<string, unknown>();
669→              for (const msg of messages) {
670→                if (msg.role === 'TOOL' && msg.toolCallId) {
671→                  let output: unknown;
672→                  if (msg.toolResult) {
673→                    output = msg.toolResult;
674→                  } else {
675→                    try {
676→                      output = JSON.parse(msg.content || '{}');
677→                    } catch {
678→                      output = { result: msg.content };
679→                    }
680→                  }
681→                  toolResultsMap.set(msg.toolCallId, output);
682→                }
683→              }
684→
685→              return messages.map((message) => {
686→                const hasEmbeddedToolCalls =
687→                  message.role === 'ASSISTANT' &&
688→                  message.toolCalls &&
689→                  Array.isArray(message.toolCalls) &&
690→                  message.toolCalls.length > 0;
691→
692→                return (
693→                  <div key={message.id} className="space-y-2">
694→                    {/* Render embedded tool calls from ASSISTANT messages */}
695→                    {hasEmbeddedToolCalls && (
696→                      <div className="space-y-2">
697→                        {message.toolCalls?.map((tc) => {
698→                          const toolOutput = toolResultsMap.get(tc.toolCallId);
699→                          const hasOutput = toolOutput !== undefined;
700→
701→                          return (
702→                            <div key={tc.toolCallId} className="flex justify-start">
703→                              <div className="max-w-[85%]">
704→                                <ToolCallCard
705→                                  toolCall={{
706→                                    toolCallId: tc.toolCallId,
707→                                    toolName: tc.toolName,
708→                                    input: tc.args,
709→                                    output: toolOutput,
710→                                    status: hasOutput ? 'success' : 'pending',
711→                                  }}
712→                                  isExpanded={expandedToolCalls.has(tc.toolCallId)}
713→                                  onToggle={() => toggleToolCall(tc.toolCallId)}
714→                                />
715→                              </div>
716→                            </div>
717→                          );
718→                        })}
719→                      </div>
720→                    )}
721→
722→                    {/* Render the message content - skip TOOL messages */}
723→                    {message.role !== 'TOOL' && (
724→                      <div
725→                        className={`flex ${message.role === 'USER' ? 'justify-end' : 'justify-start'}`}
726→                      >
727→                        <div
728→                          className={`max-w-[85%] rounded-lg p-4 ${
729→                            message.role === 'USER'
730→                              ? 'bg-primary text-primary-foreground'
731→                              : 'bg-surface text-foreground border border-dashed border-border'
732→                          }`}
733→                        >
734→                          {message.role === 'USER' ? (
735→                            <div className="text-sm whitespace-pre-wrap">{message.content}</div>
736→                          ) : (
737→                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
738→                              <Streamdown>{message.content}</Streamdown>
739→                            </div>
740→                          )}
741→                        </div>
742→                      </div>
743→                    )}
744→                  </div>
745→                );
746→              });
747→            })()}
748→
749→            {/* Live tool calls during streaming */}
750→            {toolCalls.length > 0 && (
751→              <div className="space-y-2">
752→                {toolCalls.map((tc) => (
753→                  <div key={tc.toolCallId} className="flex justify-start">
754→                    <div className="max-w-[85%]">
755→                      <ToolCallCard
756→                        toolCall={tc}
757→                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
758→                        onToggle={() => toggleToolCall(tc.toolCallId)}
759→                      />
760→                    </div>
761→                  </div>
762→                ))}
763→              </div>
764→            )}
765→
766→            {streamingContent && (
767→              <div className="flex justify-start">
768→                <div className="max-w-[85%] rounded-lg p-4 bg-surface border border-dashed border-border">
769→                  <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
770→                    <Streamdown>{streamingContent}</Streamdown>
771→                  </div>
772→                  <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
773→                </div>
774→              </div>
775→            )}
776→
777→            {isSending && !streamingContent && toolCalls.length === 0 && (
778→              <div className="flex justify-start">
779→                <div className="rounded-lg p-4 bg-surface border border-dashed border-border">
780→                  <div className="flex items-center gap-2 text-foreground-secondary">
781→                    <Icon icon="loader" size="sm" className="animate-spin" />
782→                    <span className="text-sm font-mono lowercase">thinking...</span>
783→                  </div>
784→                </div>
785→              </div>
786→            )}
787→
788→            <div ref={messagesEndRef} />
789→          </div>
790→
791→          {/* Error Message */}
792→          {error && (
793→            <div className="px-4 py-2 bg-error/10 border-t border-dashed border-error/20">
794→              <p className="text-sm text-error font-mono">{error}</p>
795→            </div>
796→          )}
797→
798→          {/* Input Area */}
799→          <div className="border-t border-dashed border-border p-4 bg-surface">
800→            <div className="flex items-end gap-2">
801→              <Textarea
802→                ref={inputRef}
803→                value={input}
804→                onChange={(e) => setInput(e.target.value)}
805→                onKeyDown={handleKeyDown}
806→                placeholder="Type a message..."
807→                rows={1}
808→                resize="none"
809→                className="flex-1 min-h-[48px] max-h-[200px] font-mono"
810→                style={{
811→                  height: 'auto',
812→                  minHeight: '48px',
813→                }}
814→                onInput={(e) => {
815→                  const target = e.target as HTMLTextAreaElement;
816→                  target.style.height = 'auto';
817→                  target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
818→                }}
819→              />
820→              <Button onClick={handleSend} disabled={isSending || !input.trim()}>
821→                <Icon icon="send" size="sm" />
822→              </Button>
823→            </div>
824→            <p className="text-[10px] text-foreground-tertiary mt-2 font-mono">
825→              enter to send, shift+enter for new line
826→            </p>
827→          </div>
828→        </div>
829→
830→        {/* Tools Panel */}
831→        <ChatToolsPanel
832→          tools={agent.tools}
833→          collections={agent.collections}
834→          isOpen={showToolsPanel}
835→          onClose={() => setShowToolsPanel(false)}
836→          onToolClick={setSelectedTool}
837→        />
838→
839→        {/* Sandbox Logs Panel */}
840→        {agent.sandboxEnabled && (
841→          <ConversationSandboxLogs
842→            agentId={agentId}
843→            conversationSlug={chatId}
844→            isOpen={showSandboxLogs}
845→            onClose={() => setShowSandboxLogs(false)}
846→          />
847→        )}
848→      </div>
849→
850→      {/* Tool Details Modal */}
851→      <ToolDetailsModal
852→        tool={selectedTool}
853→        open={!!selectedTool}
854→        onClose={() => setSelectedTool(null)}
855→      />
856→
857→      {/* Settings Drawer */}
858→      <ChatSettingsDrawer
859→        open={showSettings}
860→        onClose={() => setShowSettings(false)}
861→        agentId={agent.id}
862→        settings={{
863→          name: agent.name,
864→          provider: agent.provider,
865→          modelId: agent.modelId,
866→          systemPrompt: agent.systemPrompt,
867→          temperature: agent.temperature,
868→          maxToolCallsPerTurn: agent.maxToolCallsPerTurn,
869→          maxMessagesInContext: agent.maxMessagesInContext,
870→        }}
871→        onSettingsChange={handleSettingsChange}
872→      />
873→    </DashboardLayout>
874→  );
875→}
