  1→/**
  2→ * Agent Conversation Endpoint (Username/Slug-based version)
  3→ *
  4→ * POST: Send a message and stream the AI response
  5→ * GET: Retrieve conversation history
  6→ * DELETE: Delete a conversation
  7→ *
  8→ * This endpoint uses username and agent slug for public-friendly URLs.
  9→ * Example: /api/ajax/agents/tpmjs-discord/conversation/my-conv-1
 10→ *
 11→ * Authentication: Supports both session auth and TPMJS API key auth.
 12→ * Requires 'agent:chat' scope for API key access.
 13→ */
 14→
 15→import { Prisma, prisma } from '@tpmjs/db';
 16→import type { AIProvider } from '@tpmjs/types/agent';
 17→import { SendMessageSchema } from '@tpmjs/types/agent';
 18→import type { LanguageModel, ModelMessage } from 'ai';
 19→import { type NextRequest, NextResponse } from 'next/server';
 20→import { decryptApiKey } from '@/lib/crypto/api-keys';
 21→import { logActivity } from '~/lib/activity';
 22→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 23→import { trackUsage } from '~/lib/api-keys/usage';
 24→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 25→import { trackExecution } from '~/lib/tracking/executions';
 26→
 27→/**
 28→ * Rate limit for chat messages: 30 requests per minute
 29→ * This is stricter than default because chat involves expensive LLM calls
 30→ */
 31→const CHAT_RATE_LIMIT: RateLimitConfig = {
 32→  limit: 30,
 33→  windowSeconds: 60,
 34→};
 35→
 36→export const runtime = 'nodejs';
 37→export const dynamic = 'force-dynamic';
 38→export const maxDuration = 300; // 5 minutes for long agentic runs
 39→
 40→type RouteContext = {
 41→  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
 42→};
 43→
 44→/**
 45→ * Get AI provider SDK based on provider type
 46→ */
 47→async function getProviderModel(
 48→  provider: AIProvider,
 49→  modelId: string,
 50→  apiKey: string
 51→): Promise<LanguageModel> {
 52→  switch (provider) {
 53→    case 'OPENAI': {
 54→      const { createOpenAI } = await import('@ai-sdk/openai');
 55→      return createOpenAI({ apiKey })(modelId);
 56→    }
 57→    case 'ANTHROPIC': {
 58→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 59→      return createAnthropic({ apiKey })(modelId);
 60→    }
 61→    case 'GOOGLE': {
 62→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 63→      return createGoogleGenerativeAI({ apiKey })(modelId);
 64→    }
 65→    case 'GROQ': {
 66→      const { createGroq } = await import('@ai-sdk/groq');
 67→      return createGroq({ apiKey })(modelId);
 68→    }
 69→    case 'MISTRAL': {
 70→      const { createMistral } = await import('@ai-sdk/mistral');
 71→      return createMistral({ apiKey })(modelId);
 72→    }
 73→    default:
 74→      throw new Error(`Unsupported provider: ${provider}`);
 75→  }
 76→}
 77→
 78→/**
 79→ * POST /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 80→ * Send a message and stream the AI response via SSE
 81→ */
 82→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 83→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 84→  const startTime = Date.now();
 85→
 86→  // Authenticate request (supports both session and API key)
 87→  const authResult = await authenticateRequest();
 88→
 89→  if (!authResult.authenticated) {
 90→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 91→  }
 92→
 93→  // Check scope for API key auth
 94→  if (authResult.authenticated && !authResult.isSessionAuth) {
 95→    if (!hasScope(authResult, 'agent:chat')) {
 96→      return NextResponse.json(
 97→        { error: 'API key does not have agent:chat scope' },
 98→        { status: 403 }
 99→      );
100→    }
101→  }
102→
103→  // Check rate limit (after auth so we can track by user if needed)
104→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
105→  if (rateLimitResponse) {
106→    return rateLimitResponse;
107→  }
108→
109→  const { username, agentSlug, conversationId } = await context.params;
110→
111→  try {
112→    const body = await request.json();
113→    const parsed = SendMessageSchema.safeParse(body);
114→    if (!parsed.success) {
115→      return NextResponse.json(
116→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
117→        { status: 400 }
118→      );
119→    }
120→
121→    // Fetch agent by username and slug with all tool relations
122→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
123→      '@/lib/agents/build-tools'
124→    );
125→    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Owner-only enforcement: Only the agent owner can chat with the agent
132→    if (authResult.userId !== agent.userId) {
133→      return NextResponse.json(
134→        {
135→          success: false,
136→          error:
137→            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
138→            'Visit the agent page to fork it to your account.',
139→        },
140→        { status: 403 }
141→      );
142→    }
143→
144→    // Map provider to expected key name format
145→    const providerKeyNames: Record<string, string> = {
146→      OPENAI: 'OPENAI_API_KEY',
147→      ANTHROPIC: 'ANTHROPIC_API_KEY',
148→      GOOGLE: 'GOOGLE_API_KEY',
149→      GROQ: 'GROQ_API_KEY',
150→      MISTRAL: 'MISTRAL_API_KEY',
151→    };
152→    const keyName = providerKeyNames[agent.provider];
153→
154→    if (!keyName) {
155→      return NextResponse.json(
156→        { success: false, error: `Unsupported provider: ${agent.provider}` },
157→        { status: 400 }
158→      );
159→    }
160→
161→    // Get user's API key for this provider
162→    const userApiKey = await prisma.userApiKey.findUnique({
163→      where: {
164→        userId_keyName: {
165→          userId: agent.userId,
166→          keyName,
167→        },
168→      },
169→    });
170→
171→    if (!userApiKey) {
172→      return NextResponse.json(
173→        {
174→          success: false,
175→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→        },
177→        { status: 400 }
178→      );
179→    }
180→
181→    // Decrypt the API key
182→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→
184→    // Get or create conversation
185→    let conversation = await prisma.conversation.findUnique({
186→      where: {
187→        agentId_slug: {
188→          agentId: agent.id,
189→          slug: conversationId,
190→        },
191→      },
192→    });
193→
194→    if (!conversation) {
195→      conversation = await prisma.conversation.create({
196→        data: {
197→          agentId: agent.id,
198→          slug: conversationId,
199→          title: parsed.data.message.slice(0, 100),
200→        },
201→      });
202→
203→      // Log activity for new conversation (fire-and-forget)
204→      if (agent.userId) {
205→        logActivity({
206→          userId: agent.userId,
207→          type: 'AGENT_CONVERSATION_STARTED',
208→          targetName: agent.name,
209→          targetType: 'agent',
210→          agentId: agent.id,
211→        });
212→      }
213→    }
214→
215→    // Fetch recent messages for context
216→    const recentMessages = await prisma.message.findMany({
217→      where: { conversationId: conversation.id },
218→      orderBy: { createdAt: 'desc' },
219→      take: agent.maxMessagesInContext,
220→    });
221→
222→    // Reverse to get chronological order
223→    recentMessages.reverse();
224→
225→    // Save user message
226→    await prisma.message.create({
227→      data: {
228→        conversationId: conversation.id,
229→        role: 'USER',
230→        content: parsed.data.message,
231→      },
232→    });
233→
234→    // Build AI SDK messages from conversation history
235→    const { streamText, stepCountIs } = await import('ai');
236→
237→    const messages: ModelMessage[] = [];
238→
239→    // Add system prompt if defined
240→    if (agent.systemPrompt) {
241→      messages.push({
242→        role: 'system',
243→        content: agent.systemPrompt,
244→      });
245→    }
246→
247→    // Build a set of tool call IDs that have corresponding tool results
248→    // This is needed because AI SDK requires every tool call to have a matching tool result
249→    const toolResultIds = new Set(
250→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
251→    );
252→
253→    // Add conversation history - properly format for AI SDK
254→    for (const msg of recentMessages) {
255→      if (msg.role === 'USER') {
256→        messages.push({ role: 'user', content: msg.content });
257→      } else if (msg.role === 'ASSISTANT') {
258→        // For assistant messages with tool calls, include ToolCallParts in content
259→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
260→          // Only include tool calls that have matching tool results
261→          // AI SDK fails if there's a tool call without a corresponding tool result
262→          const validToolCalls = (
263→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
264→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
265→
266→          if (validToolCalls.length > 0) {
267→            const toolCallParts = validToolCalls.map((tc) => ({
268→              type: 'tool-call' as const,
269→              toolCallId: tc.toolCallId,
270→              toolName: tc.toolName,
271→              input: tc.args,
272→            }));
273→            // Content includes text (if any) plus tool call parts
274→            const content: Array<
275→              | { type: 'text'; text: string }
276→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
277→            > = [];
278→            if (msg.content) {
279→              content.push({ type: 'text', text: msg.content });
280→            }
281→            content.push(...toolCallParts);
282→            messages.push({
283→              role: 'assistant',
284→              content,
285→            });
286→          } else {
287→            // All tool calls are missing results, just include text content
288→            messages.push({
289→              role: 'assistant',
290→              content: msg.content || '',
291→            });
292→          }
293→        } else {
294→          messages.push({
295→            role: 'assistant',
296→            content: msg.content,
297→          });
298→        }
299→      } else if (msg.role === 'TOOL') {
300→        // Tool results use the 'tool' role with content array
301→        messages.push({
302→          role: 'tool',
303→          content: [
304→            {
305→              type: 'tool-result' as const,
306→              toolCallId: msg.toolCallId || '',
307→              toolName: msg.toolName || '',
308→              output: {
309→                type: 'json' as const,
310→                value: msg.toolResult,
311→              },
312→            },
313→          ],
314→        });
315→      }
316→    }
317→
318→    // Add new user message
319→    messages.push({ role: 'user', content: parsed.data.message });
320→
321→    // Set up sandbox session if agent has sandbox enabled
322→    let sessionId: string | undefined;
323→    let _sandboxUrl: string | undefined;
324→    let _sandboxApiKey: string | undefined;
325→    if (agent.sandboxEnabled) {
326→      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
327→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
328→      if (!sandboxUrl) {
329→        return NextResponse.json(
330→          {
331→            success: false,
332→            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
333→          },
334→          { status: 502 }
335→        );
336→      }
337→      _sandboxUrl = sandboxUrl;
338→      _sandboxApiKey = sandboxApiKey;
339→      sessionId = `${agent.id}:${conversationId}`;
340→      try {
341→        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
342→      } catch (error) {
343→        console.error('[Sandbox] Failed to create session:', error);
344→        return NextResponse.json(
345→          {
346→            success: false,
347→            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
348→          },
349→          { status: 502 }
350→        );
351→      }
352→    }
353→
354→    // Build tools from agent configuration
355→    const tools = buildAgentTools(agent, undefined, sessionId, _sandboxUrl, _sandboxApiKey);
356→
357→    // Get the provider model
358→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
359→
360→    // Create SSE stream
361→    const stream = new ReadableStream({
362→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
363→      async start(controller) {
364→        const encoder = new TextEncoder();
365→
366→        const sendEvent = (event: string, data: unknown) => {
367→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
368→          controller.enqueue(encoder.encode(message));
369→        };
370→
371→        try {
372→          const startTime = Date.now();
373→          let fullContent = '';
374→          // Accumulate tool calls with their input args
375→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
376→            new Map();
377→          // Collect tool results to save AFTER assistant message (for correct chronological order)
378→          const pendingToolResults: Array<{
379→            toolCallId: string;
380→            toolName: string;
381→            output: unknown;
382→          }> = [];
383→          let inputTokens = 0;
384→          let outputTokens = 0;
385→
386→          // Stream the response with agentic loop control
387→          const result = await streamText({
388→            model,
389→            messages,
390→            tools,
391→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
392→            onChunk: async ({ chunk }) => {
393→              // Stream tool calls as they come in and capture their inputs
394→              if (chunk.type === 'tool-call') {
395→                const input = 'args' in chunk ? chunk.args : chunk.input;
396→
397→                // Log tool call for debugging
398→                console.log('[Agent] Tool call initiated:', {
399→                  toolName: chunk.toolName,
400→                  toolCallId: chunk.toolCallId,
401→                  input: JSON.stringify(input).slice(0, 500),
402→                });
403→
404→                // Store tool call with input for later persistence
405→                toolCallsMap.set(chunk.toolCallId, {
406→                  toolCallId: chunk.toolCallId,
407→                  toolName: chunk.toolName,
408→                  args: input,
409→                });
410→                sendEvent('tool_call', {
411→                  toolCallId: chunk.toolCallId,
412→                  toolName: chunk.toolName,
413→                  input,
414→                });
415→              }
416→            },
417→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
418→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
419→              // Capture tool calls from step finish (backup in case onChunk missed any)
420→              if (toolCalls && Array.isArray(toolCalls)) {
421→                for (const tc of toolCalls) {
422→                  if (!toolCallsMap.has(tc.toolCallId)) {
423→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
424→                    const args =
425→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
426→                    toolCallsMap.set(tc.toolCallId, {
427→                      toolCallId: tc.toolCallId,
428→                      toolName: tc.toolName,
429→                      args,
430→                    });
431→                  }
432→                }
433→              }
434→
435→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
436→              if (toolResults && toolResults.length > 0) {
437→                for (const tr of toolResults) {
438→                  // Check if this is an error result (AI SDK wraps errors in the output)
439→                  const isError =
440→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
441→
442→                  // Log tool results for debugging
443→                  if (isError) {
444→                    console.error('[Agent] Tool execution failed:', {
445→                      toolName: tr.toolName,
446→                      toolCallId: tr.toolCallId,
447→                      error: tr.output,
448→                    });
449→                  } else {
450→                    console.log('[Agent] Tool execution success:', {
451→                      toolName: tr.toolName,
452→                      toolCallId: tr.toolCallId,
453→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
454→                    });
455→                  }
456→
457→                  sendEvent('tool_result', {
458→                    toolCallId: tr.toolCallId,
459→                    output: tr.output,
460→                    isError,
461→                  });
462→
463→                  // Collect tool results to save after assistant message
464→                  pendingToolResults.push({
465→                    toolCallId: tr.toolCallId,
466→                    toolName: tr.toolName,
467→                    output: tr.output,
468→                  });
469→
470→                  // Track each tool call execution event
471→                  trackExecution({
472→                    eventType: 'tool_call',
473→                    source: 'agent_chat',
474→                    userId: authResult.userId ?? undefined,
475→                    apiKeyId: authResult.apiKeyId ?? undefined,
476→                    agentId: agent.id,
477→                    toolName: tr.toolName,
478→                    status: isError ? 'error' : 'success',
479→                  });
480→                }
481→              }
482→
483→              // Track token usage
484→              if (usage) {
485→                inputTokens += usage.inputTokens ?? 0;
486→                outputTokens += usage.outputTokens ?? 0;
487→              }
488→            },
489→          });
490→
491→          // Stream text chunks
492→          for await (const chunk of result.textStream) {
493→            fullContent += chunk;
494→            sendEvent('chunk', { type: 'text', text: chunk });
495→          }
496→
497→          // Get final response data
498→          const finalUsage = await result.usage;
499→
500→          // Convert tool calls map to array for storage
501→          const allToolCalls = Array.from(toolCallsMap.values());
502→
503→          // Update token counts from final usage
504→          if (finalUsage) {
505→            inputTokens = finalUsage.inputTokens ?? inputTokens;
506→            outputTokens = finalUsage.outputTokens ?? outputTokens;
507→          }
508→
509→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
510→          const assistantMessage = await prisma.message.create({
511→            data: {
512→              conversationId: conversation.id,
513→              role: 'ASSISTANT',
514→              content: fullContent,
515→              // Cast to Prisma-compatible JSON type
516→              toolCalls:
517→                allToolCalls.length > 0
518→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
519→                  : Prisma.JsonNull,
520→              inputTokens,
521→              outputTokens,
522→            },
523→          });
524→
525→          // Now save TOOL messages (after assistant, for correct chronological order)
526→          for (const tr of pendingToolResults) {
527→            await prisma.message.create({
528→              data: {
529→                conversationId: conversation.id,
530→                role: 'TOOL',
531→                content: JSON.stringify(tr.output),
532→                toolCallId: tr.toolCallId,
533→                toolName: tr.toolName,
534→                toolResult: tr.output as object,
535→              },
536→            });
537→          }
538→
539→          // Update conversation timestamp
540→          await prisma.conversation.update({
541→            where: { id: conversation.id },
542→            data: { updatedAt: new Date() },
543→          });
544→
545→          const executionTimeMs = Date.now() - startTime;
546→
547→          // Send token usage
548→          sendEvent('tokens', {
549→            inputTokens,
550→            outputTokens,
551→            totalTokens: inputTokens + outputTokens,
552→          });
553→
554→          // Send completion event
555→          sendEvent('complete', {
556→            messageId: assistantMessage.id,
557→            conversationId: conversation.id,
558→            executionTimeMs,
559→          });
560→
561→          // Track agent run execution event
562→          trackExecution({
563→            eventType: 'agent_run',
564→            source: 'agent_chat',
565→            userId: authResult.userId ?? undefined,
566→            apiKeyId: authResult.apiKeyId ?? undefined,
567→            agentId: agent.id,
568→            status: 'success',
569→            durationMs: executionTimeMs,
570→            tokensIn: inputTokens,
571→            tokensOut: outputTokens,
572→          });
573→
574→          // Track usage
575→          if (authResult.userId) {
576→            trackUsage({
577→              apiKeyId: authResult.apiKeyId ?? undefined,
578→              userId: authResult.userId,
579→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
580→              method: 'POST',
581→              statusCode: 200,
582→              latencyMs: executionTimeMs,
583→              resourceType: 'agent',
584→              resourceId: agent.id,
585→              tokensIn: inputTokens,
586→              tokensOut: outputTokens,
587→              model: agent.modelId,
588→            });
589→          }
590→        } catch (error) {
591→          // Log detailed error for debugging
592→          console.error('[Agent] Conversation stream error:', {
593→            error: error instanceof Error ? error.message : String(error),
594→            stack: error instanceof Error ? error.stack : undefined,
595→            agentId: agent.id,
596→            conversationId: conversation.id,
597→          });
598→
599→          // Warn about orphaned sandbox session (TTL cleanup will handle it)
600→          if (sessionId && _sandboxUrl) {
601→            console.warn('[Sandbox] Stream error with active session — will expire via TTL:', {
602→              sessionId,
603→              sandboxUrl: _sandboxUrl,
604→            });
605→          }
606→          sendEvent('error', {
607→            message: error instanceof Error ? error.message : 'Unknown error',
608→          });
609→
610→          // Track agent run error
611→          trackExecution({
612→            eventType: 'agent_run',
613→            source: 'agent_chat',
614→            userId: authResult.userId ?? undefined,
615→            apiKeyId: authResult.apiKeyId ?? undefined,
616→            agentId: agent.id,
617→            status: 'error',
618→            durationMs: Date.now() - startTime,
619→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
620→          });
621→
622→          // Track error
623→          if (authResult.userId) {
624→            trackUsage({
625→              apiKeyId: authResult.apiKeyId ?? undefined,
626→              userId: authResult.userId,
627→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
628→              method: 'POST',
629→              statusCode: 500,
630→              latencyMs: Date.now() - startTime,
631→              resourceType: 'agent',
632→              resourceId: agent.id,
633→              errorCode: 'STREAM_ERROR',
634→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
635→            });
636→          }
637→        } finally {
638→          controller.close();
639→        }
640→      },
641→    });
642→
643→    return new NextResponse(stream, {
644→      headers: {
645→        'Content-Type': 'text/event-stream',
646→        'Cache-Control': 'no-cache',
647→        Connection: 'keep-alive',
648→      },
649→    });
650→  } catch (error) {
651→    console.error('Failed to process message:', error);
652→    return NextResponse.json(
653→      {
654→        success: false,
655→        error: error instanceof Error ? error.message : 'Failed to process message',
656→      },
657→      { status: 500 }
658→    );
659→  }
660→}
661→
662→/**
663→ * GET /api/[username]/agents/[agentSlug]/conversation/[conversationId]
664→ * Retrieve conversation history with pagination
665→ */
666→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
667→  const { username, agentSlug, conversationId } = await context.params;
668→  const { searchParams } = new URL(request.url);
669→
670→  const format = searchParams.get('format');
671→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
672→  const before = searchParams.get('before');
673→  const after = searchParams.get('after');
674→
675→  try {
676→    // Fetch agent by username and slug
677→    const agent = await prisma.agent.findFirst({
678→      where: {
679→        uid: agentSlug,
680→        user: { username },
681→      },
682→      select: {
683→        id: true,
684→        uid: true,
685→        name: true,
686→        provider: true,
687→        modelId: true,
688→        sandboxEnabled: true,
689→        executorType: true,
690→        executorConfig: true,
691→      },
692→    });
693→
694→    if (!agent) {
695→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
696→    }
697→
698→    // Fetch conversation
699→    const conversation = await prisma.conversation.findUnique({
700→      where: {
701→        agentId_slug: {
702→          agentId: agent.id,
703→          slug: conversationId,
704→        },
705→      },
706→    });
707→
708→    if (!conversation) {
709→      return NextResponse.json(
710→        { success: false, error: 'Conversation not found' },
711→        { status: 404 }
712→      );
713→    }
714→
715→    // For JSON format, return all messages with full details
716→    if (format === 'json') {
717→      const allMessages = await prisma.message.findMany({
718→        where: { conversationId: conversation.id },
719→        orderBy: { createdAt: 'asc' },
720→      });
721→
722→      const response = {
723→        _meta: {
724→          exportedAt: new Date().toISOString(),
725→          format: 'tpmjs-conversation-log',
726→          version: '1.0',
727→        },
728→        agent: {
729→          id: agent.id,
730→          uid: agent.uid,
731→          name: agent.name,
732→          provider: agent.provider,
733→          modelId: agent.modelId,
734→          executorType: agent.executorType,
735→          executorConfig: agent.executorConfig,
736→        },
737→        conversation: {
738→          id: conversation.id,
739→          slug: conversation.slug,
740→          title: conversation.title,
741→          createdAt: conversation.createdAt,
742→          updatedAt: conversation.updatedAt,
743→          messageCount: allMessages.length,
744→        },
745→        messages: allMessages.map((m) => ({
746→          id: m.id,
747→          role: m.role,
748→          content: m.content,
749→          toolCalls: m.toolCalls,
750→          toolCallId: m.toolCallId,
751→          toolName: m.toolName,
752→          toolResult: m.toolResult,
753→          inputTokens: m.inputTokens,
754→          outputTokens: m.outputTokens,
755→          createdAt: m.createdAt,
756→        })),
757→        stats: {
758→          totalMessages: allMessages.length,
759→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
760→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
761→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
762→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
763→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
764→        },
765→      };
766→
767→      // Return pretty-printed JSON with proper content type
768→      return new NextResponse(JSON.stringify(response, null, 2), {
769→        headers: {
770→          'Content-Type': 'application/json',
771→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
772→        },
773→      });
774→    }
775→
776→    // Standard paginated response
777→    const whereClause: {
778→      conversationId: string;
779→      createdAt?: { lt?: Date; gt?: Date };
780→    } = { conversationId: conversation.id };
781→
782→    if (before) {
783→      whereClause.createdAt = { lt: new Date(before) };
784→    } else if (after) {
785→      whereClause.createdAt = { gt: new Date(after) };
786→    }
787→
788→    // Determine fetch order:
789→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
790→    // - "after": Fetch asc (oldest first) to get messages after the cursor
791→    const shouldFetchDesc = !after;
792→
793→    // Fetch messages
794→    const messages = await prisma.message.findMany({
795→      where: whereClause,
796→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
797→      take: limit + 1,
798→    });
799→
800→    const hasMore = messages.length > limit;
801→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
802→
803→    // Reverse if we fetched in desc order to maintain chronological order
804→    if (shouldFetchDesc) {
805→      paginatedMessages = paginatedMessages.reverse();
806→    }
807→
808→    const mappedMessages = paginatedMessages.map((m) => ({
809→      id: m.id,
810→      role: m.role,
811→      content: m.content,
812→      toolCalls: m.toolCalls,
813→      toolCallId: m.toolCallId,
814→      toolName: m.toolName,
815→      toolResult: m.toolResult,
816→      inputTokens: m.inputTokens,
817→      outputTokens: m.outputTokens,
818→      createdAt: m.createdAt,
819→    }));
820→
821→    return NextResponse.json({
822→      success: true,
823→      data: {
824→        id: conversation.id,
825→        slug: conversation.slug,
826→        title: conversation.title,
827→        createdAt: conversation.createdAt,
828→        updatedAt: conversation.updatedAt,
829→        messages: mappedMessages,
830→      },
831→      pagination: {
832→        limit,
833→        hasMore,
834→        ...(before && { before }),
835→        ...(after && { after }),
836→      },
837→    });
838→  } catch (error) {
839→    console.error('Failed to fetch conversation:', error);
840→    return NextResponse.json(
841→      { success: false, error: 'Failed to fetch conversation' },
842→      { status: 500 }
843→    );
844→  }
845→}
846→
847→/**
848→ * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
849→ * Delete a conversation
850→ */
851→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
852→  const { username, agentSlug, conversationId } = await context.params;
853→
854→  try {
855→    // Fetch agent by username and slug (include sandboxEnabled for cleanup)
856→    const agent = await prisma.agent.findFirst({
857→      where: {
858→        uid: agentSlug,
859→        user: { username },
860→      },
861→      select: { id: true, sandboxEnabled: true },
862→    });
863→
864→    if (!agent) {
865→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
866→    }
867→
868→    // Destroy sandbox session if applicable (fire-and-forget)
869→    if (agent.sandboxEnabled) {
870→      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
871→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
872→      if (sandboxUrl) {
873→        const sessionId = `${agent.id}:${conversationId}`;
874→        destroySandboxSession(sandboxUrl, sandboxApiKey, sessionId).catch(() => {});
875→      }
876→    }
877→
878→    // Delete conversation (messages cascade)
879→    await prisma.conversation.deleteMany({
880→      where: {
881→        agentId: agent.id,
882→        slug: conversationId,
883→      },
884→    });
885→
886→    return NextResponse.json({
887→      success: true,
888→      data: { deleted: true },
889→    });
890→  } catch (error) {
891→    console.error('Failed to delete conversation:', error);
892→    return NextResponse.json(
893→      { success: false, error: 'Failed to delete conversation' },
894→      { status: 500 }
895→    );
896→  }
897→}
