'use client';

import type { AIProvider } from '@tpmjs/types/agent';
import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Virtuoso, type VirtuosoHandle } from 'react-virtuoso';
import { Streamdown } from 'streamdown';
import { AppHeader } from '~/components/AppHeader';
import { LikeButton } from '~/components/LikeButton';

interface AgentTool {
  id: string;
  toolId: string;
  position: number;
  tool: {
    id: string;
    name: string;
    description: string;
    likeCount: number;
    package: {
      id: string;
      npmPackageName: string;
      category: string;
    };
  };
}

interface AgentCollection {
  id: string;
  collectionId: string;
  position: number;
  collection: {
    id: string;
    name: string;
    description: string | null;
    toolCount: number;
  };
}

interface Agent {
  id: string;
  uid: string;
  name: string;
  description: string | null;
  provider: AIProvider;
  modelId: string;
  systemPrompt: string | null;
  temperature: number;
  maxToolCallsPerTurn: number;
  likeCount: number;
  toolCount: number;
  collectionCount: number;
  createdBy: {
    id: string;
    username: string | null;
    name: string;
    image: string | null;
  };
  tools: AgentTool[];
  collections: AgentCollection[];
}

interface Message {
  id: string;
  role: 'USER' | 'ASSISTANT' | 'TOOL';
  content: string;
  toolName?: string;
  toolCallId?: string;
  toolResult?: unknown;
  toolCalls?: Array<{
    toolCallId: string;
    toolName: string;
    args: unknown;
  }>;
  inputTokens?: number;
  outputTokens?: number;
  createdAt: string;
}

interface ToolCall {
  toolCallId: string;
  toolName: string;
  input?: unknown;
  output?: unknown;
  status: 'pending' | 'running' | 'success' | 'error';
}

/**
 * Tool call debug card component
 */
function ToolCallCard({
  toolCall,
  isExpanded,
  onToggle,
}: {
  toolCall: ToolCall;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  const statusColors = {
    pending: 'bg-warning/10 text-warning border-warning/30',
    running: 'bg-info/10 text-info border-info/30',
    success: 'bg-success/10 text-success border-success/30',
    error: 'bg-error/10 text-error border-error/30',
  };

  const statusIcons: Record<ToolCall['status'], 'loader' | 'check' | 'alertCircle' | 'info'> = {
    pending: 'info',
    running: 'loader',
    success: 'check',
    error: 'alertCircle',
  };

  const formatJson = (data: unknown): React.ReactNode => {
    try {
      return JSON.stringify(data, null, 2);
    } catch {
      return String(data);
    }
  };

  return (
    <div className="rounded-lg border border-border bg-surface-secondary/50 overflow-hidden font-mono text-xs">
      {/* Header */}
      <Button
        variant="ghost"
        onClick={onToggle}
        className="w-full flex items-center gap-3 p-3 h-auto justify-start rounded-none hover:bg-surface-secondary/80"
      >
        <div className={`p-1.5 rounded ${statusColors[toolCall.status]}`}>
          <Icon
            icon={statusIcons[toolCall.status]}
            size="xs"
            className={toolCall.status === 'running' ? 'animate-spin' : ''}
          />
        </div>
        <div className="flex-1 text-left">
          <div className="flex items-center gap-2">
            <span className="text-foreground font-semibold">{toolCall.toolName}</span>
            <span className="text-foreground-tertiary text-[10px]">
              {toolCall.toolCallId.slice(0, 8)}...
            </span>
          </div>
        </div>
        <Icon
          icon="chevronRight"
          size="xs"
          className={`text-foreground-tertiary transition-transform ${isExpanded ? 'rotate-90' : ''}`}
        />
      </Button>

      {/* Error output always visible (no need to expand) */}
      {toolCall.status === 'error' && toolCall.output !== undefined && toolCall.output !== null && (
        <div className="border-t border-error/30 bg-error/5 p-3">
          <div className="flex items-center gap-2 mb-2">
            <Icon icon="alertCircle" size="xs" className="text-error" />
            <span className="text-[10px] uppercase tracking-wider text-error font-medium">
              Error
            </span>
            <div className="flex-1 h-px bg-error/20" />
          </div>
          <pre className="text-[11px] text-error overflow-x-auto whitespace-pre-wrap break-all max-h-64 overflow-y-auto">
            {formatJson(toolCall.output)}
          </pre>
        </div>
      )}

      {/* Expanded Content */}
      {isExpanded && (
        <div className="border-t border-border">
          {/* Input Section */}
          {toolCall.input !== undefined && toolCall.input !== null ? (
            <div className="p-3 border-b border-border/50">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
                  Input
                </span>
                <div className="flex-1 h-px bg-border/50" />
              </div>
              <pre className="text-[11px] text-foreground-secondary overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto">
                {formatJson(toolCall.input)}
              </pre>
            </div>
          ) : null}

          {/* Output Section (only for non-error, since errors are shown above) */}
          {toolCall.status !== 'error' &&
          toolCall.output !== undefined &&
          toolCall.output !== null ? (
            <div className="p-3">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
                  Output
                </span>
                <div className="flex-1 h-px bg-border/50" />
              </div>
              <pre className="text-[11px] text-success overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto">
                {formatJson(toolCall.output)}
              </pre>
            </div>
          ) : null}

          {/* Status indicator for running */}
          {toolCall.status === 'running' && !toolCall.output && (
            <div className="p-3 flex items-center gap-2 text-foreground-tertiary">
              <Icon icon="loader" size="xs" className="animate-spin" />
              <span>Executing...</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

const PROVIDER_DISPLAY_NAMES: Record<AIProvider, string> = {
  OPENAI: 'OpenAI',
  ANTHROPIC: 'Anthropic',
  GOOGLE: 'Google',
  GROQ: 'Groq',
  MISTRAL: 'Mistral',
};

function generateConversationId(): string {
  return `conv-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

export default function PublicAgentChatPage(): React.ReactElement {
  const params = useParams();
  const router = useRouter();
  const agentId = params.id as string;
  const conversationId = params.chatId as string;

  const [agent, setAgent] = useState<Agent | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [expandedToolCalls, setExpandedToolCalls] = useState<Set<string>>(new Set());
  const [hasMoreMessages, setHasMoreMessages] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [viewMode, setViewMode] = useState<'chat' | 'debug'>('chat');

  // Track first item index for prepending (Virtuoso pattern)
  const [firstItemIndex, setFirstItemIndex] = useState(10000);

  const virtuosoRef = useRef<VirtuosoHandle>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const toggleToolCall = (toolCallId: string) => {
    setExpandedToolCalls((prev) => {
      const next = new Set(prev);
      if (next.has(toolCallId)) {
        next.delete(toolCallId);
      } else {
        next.add(toolCallId);
      }
      return next;
    });
  };

  // Fetch public agent data
  const fetchAgent = useCallback(async () => {
    try {
      const response = await fetch(`/api/public/agents/${agentId}`);
      const data = await response.json();

      if (data.success) {
        setAgent(data.data);
      } else {
        setError(data.error?.message || 'Agent not found or is private');
      }
    } catch (err) {
      console.error('Failed to fetch agent:', err);
      setError('Failed to fetch agent');
    }
  }, [agentId]);

  // Fetch messages for conversation (initial load - gets most recent 50)
  const fetchMessages = useCallback(async () => {
    if (!agent || !agent.createdBy.username) return;

    try {
      const response = await fetch(
        `/api/${agent.createdBy.username}/agents/${agent.uid}/conversation/${conversationId}?limit=50`
      );
      if (response.status === 404) {
        // Conversation doesn't exist yet, that's fine
        setHasMoreMessages(false);
        return;
      }
      const data = await response.json();

      if (data.success) {
        const msgs = data.data.messages || [];
        setMessages(msgs);
        setHasMoreMessages(data.pagination?.hasMore ?? false);
        // Reset first item index when loading fresh
        setFirstItemIndex(10000);
      }
    } catch (err) {
      console.error('Failed to fetch messages:', err);
    }
  }, [agent, conversationId]);

  // Load older messages when scrolling up
  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Virtuoso scroll handler with pagination logic
  const loadMoreMessages = useCallback(async () => {
    if (
      !agent ||
      !agent.createdBy.username ||
      isLoadingMore ||
      !hasMoreMessages ||
      messages.length === 0
    )
      return;

    setIsLoadingMore(true);
    try {
      // Get the timestamp of the oldest message we have
      const oldestMessage = messages[0];
      const beforeTimestamp = oldestMessage?.createdAt;

      if (!beforeTimestamp) return;

      const response = await fetch(
        `/api/${agent.createdBy.username}/agents/${agent.uid}/conversation/${conversationId}?limit=50&before=${encodeURIComponent(beforeTimestamp)}`
      );

      if (!response.ok) return;

      const data = await response.json();

      if (data.success) {
        const olderMessages = data.data.messages || [];
        if (olderMessages.length > 0) {
          // Prepend older messages and adjust firstItemIndex
          setFirstItemIndex((prev) => prev - olderMessages.length);
          setMessages((prev) => [...olderMessages, ...prev]);
        }
        setHasMoreMessages(data.pagination?.hasMore ?? false);
      }
    } catch (err) {
      console.error('Failed to load more messages:', err);
    } finally {
      setIsLoadingMore(false);
    }
  }, [agent, conversationId, isLoadingMore, hasMoreMessages, messages]);

  useEffect(() => {
    const init = async () => {
      await fetchAgent();
      setIsLoading(false);
    };
    init();
  }, [fetchAgent]);

  useEffect(() => {
    if (agent) {
      fetchMessages();
    }
  }, [agent, fetchMessages]);

  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Chat send handler with streaming and tool calls
  const handleSend = async () => {
    if (!input.trim() || !agent || !agent.createdBy.username || isSending) return;

    const messageContent = input.trim();
    setInput('');
    setIsSending(true);
    setStreamingContent('');
    setError(null);
    setToolCalls([]);

    // Optimistically add user message
    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'USER',
      content: messageContent,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMessage]);

    try {
      const response = await fetch(
        `/api/${agent.createdBy.username}/agents/${agent.uid}/conversation/${conversationId}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ message: messageContent }),
        }
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to send message');
      }

      // Handle SSE stream
      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Parse SSE events
        const lines = buffer.split('\n');
        buffer = lines.pop() || ''; // Keep incomplete line in buffer

        let eventType = '';
        for (const line of lines) {
          if (line.startsWith('event: ')) {
            eventType = line.slice(7);
          } else if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6));

            switch (eventType) {
              case 'chunk':
                setStreamingContent((prev) => prev + data.text);
                break;
              case 'tool_call':
                // Add tool call to tracking
                setToolCalls((prev) => [
                  ...prev,
                  {
                    toolCallId: data.toolCallId,
                    toolName: data.toolName,
                    input: data.input,
                    status: 'running',
                  },
                ]);
                // Auto-expand new tool calls
                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
                break;
              case 'tool_result':
                // Update tool call with result (use error status when isError flag is set)
                setToolCalls((prev) =>
                  prev.map((tc) =>
                    tc.toolCallId === data.toolCallId
                      ? {
                          ...tc,
                          output: data.output,
                          status: data.isError ? ('error' as const) : ('success' as const),
                        }
                      : tc
                  )
                );
                break;
              case 'complete':
                // Refresh messages
                await fetchMessages();
                setStreamingContent('');
                setToolCalls([]);
                break;
              case 'error':
                throw new Error(data.message);
            }
          }
        }
      }
    } catch (err) {
      console.error('Failed to send message:', err);
      setError(err instanceof Error ? err.message : 'Failed to send message');
      // Remove optimistic message on error
      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
    } finally {
      setIsSending(false);
      setStreamingContent('');
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startNewConversation = () => {
    // Navigate to new chat URL
    const newId = generateConversationId();
    router.push(`/agents/${agentId}/chat/${newId}`);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
        </div>
      </div>
    );
  }

  if (error && !agent) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="text-center">
            <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
            <h2 className="text-lg font-medium text-foreground mb-2">Unable to Chat</h2>
            <p className="text-foreground-secondary mb-4">{error}</p>
            <Link href="/agents">
              <Button>Browse Agents</Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  if (!agent) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <AppHeader />

      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar */}
        <div
          className={`${sidebarOpen ? 'w-80' : 'w-0'} transition-all duration-300 border-r border-border bg-surface/30 overflow-hidden flex-shrink-0`}
        >
          <div className="w-80 h-full overflow-y-auto p-4">
            {/* Agent Header */}
            <div className="mb-6">
              <Link
                href={`/agents/${agentId}`}
                className="inline-flex items-center gap-1 text-sm text-foreground-secondary hover:text-foreground mb-3"
              >
                <Icon icon="arrowLeft" size="xs" />
                Back to Agent
              </Link>
              <div className="flex items-start justify-between">
                <div>
                  <h2 className="text-lg font-semibold text-foreground">{agent.name}</h2>
                  {agent.description && (
                    <p className="text-sm text-foreground-secondary mt-1 line-clamp-2">
                      {agent.description}
                    </p>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-2 mt-3">
                <LikeButton
                  entityType="agent"
                  entityId={agent.id}
                  initialCount={agent.likeCount}
                  size="sm"
                  showCount={true}
                />
              </div>
            </div>

            {/* Configuration */}
            <div className="mb-6">
              <h3 className="text-sm font-medium text-foreground mb-3 flex items-center gap-2">
                <Icon icon="box" size="xs" className="text-foreground-tertiary" />
                Configuration
              </h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-foreground-tertiary">Provider</span>
                  <Badge variant="secondary" size="sm">
                    {PROVIDER_DISPLAY_NAMES[agent.provider]}
                  </Badge>
                </div>
                <div className="flex justify-between">
                  <span className="text-foreground-tertiary">Model</span>
                  <span className="text-foreground font-mono text-xs">{agent.modelId}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-foreground-tertiary">Temperature</span>
                  <span className="text-foreground">{agent.temperature}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-foreground-tertiary">Max Tool Calls</span>
                  <span className="text-foreground">{agent.maxToolCallsPerTurn}</span>
                </div>
              </div>

              {agent.systemPrompt && (
                <div className="mt-3">
                  <span className="text-xs text-foreground-tertiary block mb-1">System Prompt</span>
                  <pre className="p-2 bg-background border border-border rounded text-xs text-foreground-secondary whitespace-pre-wrap font-mono max-h-32 overflow-y-auto">
                    {agent.systemPrompt}
                  </pre>
                </div>
              )}
            </div>

            {/* Tools */}
            <div className="mb-6">
              <h3 className="text-sm font-medium text-foreground mb-3 flex items-center gap-2">
                <Icon icon="puzzle" size="xs" className="text-foreground-tertiary" />
                Tools ({agent.tools.length})
              </h3>
              {agent.tools.length === 0 ? (
                <p className="text-sm text-foreground-tertiary">No tools configured</p>
              ) : (
                <div className="space-y-2">
                  {agent.tools.map((at) => (
                    <Link
                      key={at.id}
                      href={`/tool/${at.tool.package.npmPackageName}/${at.tool.name}`}
                      className="block p-2 bg-background border border-border rounded hover:border-foreground/20 transition-colors"
                    >
                      <div className="flex items-start justify-between">
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-foreground truncate">
                            {at.tool.name}
                          </p>
                          <p className="text-xs text-foreground-tertiary truncate">
                            {at.tool.package.npmPackageName}
                          </p>
                        </div>
                        <Badge variant="secondary" size="sm" className="ml-2 flex-shrink-0">
                          {at.tool.package.category}
                        </Badge>
                      </div>
                    </Link>
                  ))}
                </div>
              )}
            </div>

            {/* Collections */}
            {agent.collections.length > 0 && (
              <div>
                <h3 className="text-sm font-medium text-foreground mb-3 flex items-center gap-2">
                  <Icon icon="folder" size="xs" className="text-foreground-tertiary" />
                  Collections ({agent.collections.length})
                </h3>
                <div className="space-y-2">
                  {agent.collections.map((ac) => (
                    <Link
                      key={ac.id}
                      href={`/collections/${ac.collection.id}`}
                      className="block p-2 bg-background border border-border rounded hover:border-foreground/20 transition-colors"
                    >
                      <p className="text-sm font-medium text-foreground truncate">
                        {ac.collection.name}
                      </p>
                      <p className="text-xs text-foreground-tertiary">
                        {ac.collection.toolCount} tools
                      </p>
                    </Link>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Main Chat Area */}
        <div className="flex-1 flex flex-col min-w-0">
          {/* Chat Header */}
          <div className="border-b border-border bg-surface/50 px-4 py-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setSidebarOpen(!sidebarOpen)}
                  title={sidebarOpen ? 'Hide sidebar' : 'Show sidebar'}
                >
                  <Icon icon="menu" size="sm" />
                </Button>
                <div>
                  <h1 className="text-lg font-semibold text-foreground">{agent.name}</h1>
                  <p className="text-sm text-foreground-tertiary">
                    {PROVIDER_DISPLAY_NAMES[agent.provider]} • {agent.modelId}
                  </p>
                </div>
              </div>
              <Button variant="outline" size="sm" onClick={startNewConversation}>
                <Icon icon="plus" size="xs" className="mr-2" />
                New Chat
              </Button>
            </div>
            {/* View Mode Tabs */}
            <div className="flex gap-1 mt-3">
              <Button
                variant={viewMode === 'chat' ? 'default' : 'ghost'}
                size="sm"
                onClick={() => setViewMode('chat')}
              >
                Chat
              </Button>
              <Button
                variant={viewMode === 'debug' ? 'default' : 'ghost'}
                size="sm"
                onClick={() => setViewMode('debug')}
              >
                Debug JSON
              </Button>
            </div>
          </div>

          {/* Debug JSON View */}
          {viewMode === 'debug' && (
            <div className="flex-1 overflow-auto p-4 bg-background">
              <div className="mb-4 flex items-start justify-between">
                <div>
                  <h2 className="text-sm font-medium text-foreground mb-2">
                    Raw Messages Array ({messages.length} messages)
                  </h2>
                  <p className="text-xs text-foreground-tertiary">
                    Messages are ordered by createdAt. Each message includes role, content, and tool
                    call data.
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    navigator.clipboard.writeText(JSON.stringify(messages, null, 2));
                  }}
                >
                  <Icon icon="copy" size="xs" className="mr-2" />
                  Copy JSON
                </Button>
              </div>
              <pre className="text-xs font-mono bg-surface-secondary border border-border rounded-lg p-4 overflow-x-auto whitespace-pre-wrap">
                {JSON.stringify(messages, null, 2)}
              </pre>
            </div>
          )}

          {/* Chat View */}
          {viewMode === 'chat' && (
            <>
              {/* Messages */}
              <div className="flex-1 overflow-hidden">
                {messages.length === 0 && !streamingContent ? (
                  <div className="h-full flex items-center justify-center p-4">
                    <div className="text-center">
                      <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
                        <Icon icon="message" size="lg" className="text-primary" />
                      </div>
                      <h3 className="text-lg font-medium text-foreground mb-2">
                        Start a conversation
                      </h3>
                      <p className="text-foreground-secondary max-w-sm">
                        Send a message to start chatting with {agent.name}.
                      </p>
                    </div>
                  </div>
                ) : (
                  <Virtuoso
                    ref={virtuosoRef}
                    className="h-full"
                    data={messages}
                    firstItemIndex={firstItemIndex}
                    initialTopMostItemIndex={messages.length - 1}
                    startReached={loadMoreMessages}
                    followOutput="smooth"
                    components={{
                      Header: () =>
                        hasMoreMessages ? (
                          <div className="flex justify-center py-4">
                            {isLoadingMore ? (
                              <div className="flex items-center gap-2 text-foreground-secondary">
                                <Icon icon="loader" size="sm" className="animate-spin" />
                                <span className="text-sm">Loading older messages...</span>
                              </div>
                            ) : (
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={loadMoreMessages}
                                className="text-primary hover:text-primary/80"
                              >
                                Load older messages
                              </Button>
                            )}
                          </div>
                        ) : null,
                      Footer: () => (
                        <div className="px-4 pb-4 space-y-4">
                          {/* Live tool calls during streaming */}
                          {toolCalls.length > 0 && (
                            <div className="space-y-2">
                              {toolCalls.map((tc) => (
                                <div key={tc.toolCallId} className="flex justify-start">
                                  <div className="max-w-[80%]">
                                    <ToolCallCard
                                      toolCall={tc}
                                      isExpanded={expandedToolCalls.has(tc.toolCallId)}
                                      onToggle={() => toggleToolCall(tc.toolCallId)}
                                    />
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}

                          {streamingContent && (
                            <div className="flex justify-start">
                              <div className="max-w-[80%] rounded-lg p-4 bg-surface-secondary">
                                <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                                  <Streamdown>{streamingContent}</Streamdown>
                                </div>
                                <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
                              </div>
                            </div>
                          )}

                          {isSending && !streamingContent && toolCalls.length === 0 && (
                            <div className="flex justify-start">
                              <div className="rounded-lg p-4 bg-surface-secondary">
                                <div className="flex items-center gap-2 text-foreground-secondary">
                                  <Icon icon="loader" size="sm" className="animate-spin" />
                                  <span className="text-sm">Thinking...</span>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                      ),
                    }}
                    itemContent={(_index, message) => {
                      // Parse tool output safely
                      const getToolOutput = () => {
                        if (message.toolResult) return message.toolResult;
                        try {
                          return JSON.parse(message.content || '{}');
                        } catch {
                          return { result: message.content };
                        }
                      };

                      // Build a lookup map for tool call inputs from ASSISTANT messages
                      // This allows us to show the input args when rendering TOOL messages
                      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Helper in virtuoso render callback
                      const getToolCallInput = (toolCallId: string): unknown => {
                        for (const msg of messages) {
                          if (msg.role === 'ASSISTANT' && msg.toolCalls) {
                            const tc = msg.toolCalls.find((t) => t.toolCallId === toolCallId);
                            if (tc) return tc.args;
                          }
                        }
                        return undefined;
                      };

                      // Check if a tool call has a corresponding TOOL message (meaning it completed)
                      const hasToolResult = (toolCallId: string): boolean => {
                        return messages.some(
                          (m) => m.role === 'TOOL' && m.toolCallId === toolCallId
                        );
                      };

                      // Detect if a tool result is an error
                      const isToolError = (output: unknown): boolean => {
                        if (output && typeof output === 'object' && 'error' in output) return true;
                        return false;
                      };

                      return (
                        <div className="px-4 py-2">
                          {/* TOOL message - shows the result of a tool call */}
                          {message.role === 'TOOL' && (
                            <div className="flex justify-start">
                              <div className="max-w-[80%]">
                                <ToolCallCard
                                  toolCall={{
                                    toolCallId: message.toolCallId || message.id,
                                    toolName: message.toolName || 'Unknown Tool',
                                    input: getToolCallInput(message.toolCallId || ''),
                                    output: getToolOutput(),
                                    status: isToolError(getToolOutput()) ? 'error' : 'success',
                                  }}
                                  isExpanded={expandedToolCalls.has(
                                    message.toolCallId || message.id
                                  )}
                                  onToggle={() => toggleToolCall(message.toolCallId || message.id)}
                                />
                              </div>
                            </div>
                          )}

                          {/* USER message */}
                          {message.role === 'USER' && (
                            <div className="flex justify-end">
                              <div className="max-w-[80%] rounded-lg p-4 bg-primary text-primary-foreground">
                                <div className="text-sm whitespace-pre-wrap">{message.content}</div>
                              </div>
                            </div>
                          )}

                          {/* ASSISTANT message - may contain text and/or tool calls */}
                          {message.role === 'ASSISTANT' && (
                            <div className="space-y-2">
                              {/* Assistant text content */}
                              {message.content && (
                                <div className="flex justify-start">
                                  <div className="max-w-[80%] rounded-lg p-4 bg-surface-secondary">
                                    <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                                      <Streamdown>{message.content}</Streamdown>
                                    </div>
                                    {/* Token usage for debugging */}
                                    {(message.inputTokens || message.outputTokens) && (
                                      <div className="mt-2 pt-2 border-t border-border/50 text-[10px] text-foreground-tertiary font-mono">
                                        {message.inputTokens && (
                                          <span>In: {message.inputTokens}</span>
                                        )}
                                        {message.inputTokens && message.outputTokens && (
                                          <span> • </span>
                                        )}
                                        {message.outputTokens && (
                                          <span>Out: {message.outputTokens}</span>
                                        )}
                                      </div>
                                    )}
                                  </div>
                                </div>
                              )}

                              {/* Show tool calls from this assistant message that don't have results yet */}
                              {message.toolCalls
                                ?.filter((tc) => !hasToolResult(tc.toolCallId))
                                .map((tc) => (
                                  <div key={tc.toolCallId} className="flex justify-start">
                                    <div className="max-w-[80%]">
                                      <ToolCallCard
                                        toolCall={{
                                          toolCallId: tc.toolCallId,
                                          toolName: tc.toolName,
                                          input: tc.args,
                                          status: 'pending',
                                        }}
                                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
                                        onToggle={() => toggleToolCall(tc.toolCallId)}
                                      />
                                    </div>
                                  </div>
                                ))}
                            </div>
                          )}
                        </div>
                      );
                    }}
                  />
                )}
              </div>

              {/* Error Message */}
              {error && (
                <div className="px-4 py-2 bg-error/10 border-t border-error/20">
                  <p className="text-sm text-error">{error}</p>
                </div>
              )}

              {/* Input Area */}
              <div className="border-t border-border p-4">
                <div className="flex items-end gap-2">
                  <Textarea
                    ref={inputRef}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Type a message..."
                    rows={1}
                    resize="none"
                    className="flex-1 min-h-[48px] max-h-[200px]"
                    style={{
                      height: 'auto',
                      minHeight: '48px',
                    }}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
                    }}
                  />
                  <Button onClick={handleSend} disabled={isSending || !input.trim()}>
                    <Icon icon="send" size="sm" />
                  </Button>
                </div>
                <p className="text-xs text-foreground-tertiary mt-2">
                  Press Enter to send, Shift+Enter for new line
                </p>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

